Framescript.script:
//for making animate fit on phones
createjs.Touch.enable(stage);
// ================================================
// MAZE CHASE - v7 FIXED
// ================================================

const stageRoot      = this;
const avatar         = this.avatar;
const questionPanel  = this.questionPanel;
const exitZone       = this.exitZone;
const timerText      = this.timerText;
const scoreText      = this.scoreText;
const timeTakenText  = this.timeTakenText || this.elapsedTimeText;
const failedScreen   = this.failedScreen;
const mazeBg         = this.mazeBG;
const moveButtons    = [this.btnUp, this.btnDown, this.btnLeft, this.btnRight].filter(Boolean);

const AVATAR_START_X = avatar ? avatar.x : 0;
const AVATAR_START_Y = avatar ? avatar.y : 0;
const AVATAR_START_SCALE_X = avatar && avatar.scaleX != null ? avatar.scaleX : 1;
const AVATAR_START_SCALE_Y = avatar && avatar.scaleY != null ? avatar.scaleY : 1;

let score                  = 0;
let lives                  = 3;
let answered               = new Set();
let gameState              = "INTRO";
let moveSpeed              = 4;
let lastTriggeredCP        = null;
let moveInterval           = null;
let timerInterval          = null;
let elapsedTime            = 0;
let currentCheckpointIndex = 0;
let checkpointCooldown     = false;
let questionLocked         = false;
let grieverContactLocked   = false;
let grievers               = [];
let grieverStartStates     = [];
let boundaryObstacles      = [];
let grieverPaths           = [];
const clipTransformCache   = new WeakMap();
let feedbackBgShape        = null;
let feedbackBgParent       = null;
let livesContainer         = null;
let lifeHearts             = [];
let currentQuestionSound   = null;
const OPTION_NAMES          = ["optA", "optB", "optC", "optD"];
const BALL_NAMES            = ["ballA", "ballB", "ballC", "ballD"];

// A fresh ball assignment is generated for every play so the correct physical
// target cannot be memorised from one run to the next.
let correctBallByQuestion = [];

const INITIAL_FEEDBACK_TEXT = "Click the blue buttons to move the avatar into the correct answer to the question below.";
const STARTING_LIVES        = 3;
const GRIEVER_SPEED         = 2.2;
const GRIEVER_CHASE_RADIUS  = 170;
const GRIEVER_CONTACT_PAD   = 4;
const GRIEVER_RANDOM_SPEED  = 1.9;
const GRIEVER_PUSH_STEPS    = 4;
const GRIEVER_PUSH_DISTANCE = 7;
const GRIEVER_PATH_JOIN_PAD = 18;
const GRIEVER_MAX_PATH_SNAP = GRIEVER_PATH_JOIN_PAD + GRIEVER_SPEED + 4;
const GRIEVER_RECENT_PATH_LIMIT = 7;
const GRIEVER_STUCK_MOVE_EPS = 0.35;
const GRIEVER_STUCK_TICKS = 10;
const GRIEVER_CENTERING_SPEED = 0.65;
const GRIEVER_OSCILLATION_LIMIT = 1;
const GRIEVER_SAME_PATH_REVERSAL_LIMIT = 2;
const GRIEVER_COLLISION_RETREAT_TICKS = 18;
const GRIEVER_COLLISION_SEPARATION = 4;
const GRIEVER_COLLISION_COOLDOWN_TICKS = 10;
const GRIEVER_COLLISION_YIELD_TICKS = 2;
const optionStartTransforms = new WeakMap();
const optionContactLocks    = new Set();
const grieverDirections     = new WeakMap();
const grieverModes          = new WeakMap();
let grieverPathStates       = new WeakMap();
const grieverReverseTicks   = new WeakMap();
const grieverCollisionCooldowns = new WeakMap();
const grieverYieldTicks = new WeakMap();
let answerCollisionArmed     = false;
const ANSWER_FEEDBACK_SECONDS = Number(stageRoot.answerFeedbackSeconds) > 0
  ? Number(stageRoot.answerFeedbackSeconds)
  : 5;
const ANSWER_FEEDBACK_MS = ANSWER_FEEDBACK_SECONDS * 1000;
const AVATAR_RETURN_MS = 760;
let answerFeedbackResetting = false;

function getCheckpointLabel(clip, index) {
  if (!clip) return null;
  if (clip._questionLabel) return clip._questionLabel;

  const label = new createjs.Text(`Q${index + 1}`, "bold 16px Arial", "#ffffff");
  label.name = `questionLabel${index + 1}`;
  label.textAlign = "center";
  label.textBaseline = "middle";
  label.mouseEnabled = false;
  label.shadow = new createjs.Shadow("rgba(0,0,0,0.65)", 0, 1, 4);

  const bounds = clip.getBounds ? clip.getBounds() : null;
  label.x = bounds ? bounds.x + bounds.width / 2 : 0;
  label.y = bounds ? bounds.y + bounds.height / 2 : 0;

  clip.addChild(label);
  clip._questionLabel = label;
  return label;
}

function refreshCheckpointLabels() {
  checkpoints.forEach((cp, index) => {
    if (!cp?.clip) return;
    const label = getCheckpointLabel(cp.clip, index);
    if (!label) return;

    label.text = `Q${index + 1}`;
    label.visible = !answered.has(cp.id) && index === currentCheckpointIndex;
    label.alpha = index === currentCheckpointIndex ? 1 : 0.45;
    label.color = index === currentCheckpointIndex ? "#fff7a8" : "#ffffff";
  });
}

// ====================== P.4 MATH QUESTION BANK ======================
const QUESTION_BANK = [
  { id: "times78", q: "What is 7 × 8?", answer: "56", wrong: ["48", "54", "64"], ok: "Correct! 7 × 8 = 56.", bad: "Not quite. Try the operation again carefully." },
  { id: "div63", q: "What is 63 ÷ 9?", answer: "7", wrong: ["6", "8", "9"], ok: "Correct! 63 ÷ 9 = 7.", bad: "Not quite. Try the operation again carefully." },
  { id: "add4537", q: "What is 45 + 37?", answer: "82", wrong: ["72", "81", "92"], ok: "Correct! 45 + 37 = 82.", bad: "Not quite. Try the operation again carefully." },
  { id: "sub10038", q: "What is 100 − 38?", answer: "62", wrong: ["58", "72", "68"], ok: "Correct! 100 − 38 = 62.", bad: "Not quite. Try the operation again carefully." },
  { id: "place5", q: "What is the place value of 5 in 3,582?", answer: "Hundreds", wrong: ["Ones", "Tens", "Thousands"], ok: "Correct! The 5 in 3,582 is in the tens place.", bad: "Not quite. Look at the place of each digit again." },
  { id: "times126", q: "What is 12 × 6?", answer: "72", wrong: ["66", "70", "78"], ok: "Correct! 12 × 6 = 72.", bad: "Not quite. Try the operation again carefully." },
  { id: "div144", q: "What is 144 ÷ 12?", answer: "12", wrong: ["11", "14", "16"], ok: "Correct! 144 ÷ 12 = 12.", bad: "Not quite. Try the operation again carefully." },
  { id: "mangoes", q: "A shop has 48 mangoes. It sells 19. How many are left?", answer: "29", wrong: ["27", "31", "39"], ok: "Correct! 48 − 19 = 29 mangoes are left.", bad: "Not quite. Subtract the mangoes sold from 48." },
  { id: "times99", q: "What is 9 × 9?", answer: "81", wrong: ["72", "89", "99"], ok: "Correct! 9 × 9 = 81.", bad: "Not quite. Try the operation again carefully." },
  { id: "round347", q: "Round 347 to the nearest 10.", answer: "350", wrong: ["340", "300", "347"], ok: "Correct! 347 rounded to the nearest 10 is 350.", bad: "Not quite. Look at the ones digit to decide how to round." }
];

let questions = [];

function shuffleArray(values) {
  const shuffled = values.slice();
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

function formatAnswer(value) {
  return String(value);
}

function buildQuestionRun() {
  questions = shuffleArray(QUESTION_BANK).map(item => {
    const rawOptions = shuffleArray([item.answer, ...item.wrong]);
    const options = rawOptions.map(formatAnswer);
    const correctIndex = options.indexOf(formatAnswer(item.answer));

    return {
      id: item.id,
      audioId: "math_" + item.id,
      q: item.q,
      o: options,
      c: correctIndex,
      ok: item.ok,
      bad: item.bad
    };
  });

  correctBallByQuestion = questions.map(() => {
    return BALL_NAMES[Math.floor(Math.random() * BALL_NAMES.length)];
  });
}

// ====================== CHECKPOINTS ======================
const checkpoints = [
  { id: "cp1",  qIndex: 0, clip: this.cp1  },
  { id: "cp2",  qIndex: 1, clip: this.cp2  },
  { id: "cp3",  qIndex: 2, clip: this.cp3  },
  { id: "cp4",  qIndex: 3, clip: this.cp4  },
  { id: "cp5",  qIndex: 4, clip: this.cp5  },
  { id: "cp6",  qIndex: 5, clip: this.cp6  },
  { id: "cp7",  qIndex: 6, clip: this.cp7  },
  { id: "cp8",  qIndex: 7, clip: this.cp8  },
  { id: "cp9",  qIndex: 8, clip: this.cp9  },
  { id: "cp10", qIndex: 9, clip: this.cp10 }
];

// ====================== WALL DATA ======================
let wallData = [];
for (let i = 1; i <= 81; i++) {
  wallData.push(this["wall" + i]);
}

// ====================== WALL COLLISION ======================
const wallPadding = 1;
const avatarHitbox = {
  insetLeft: 8,
  insetTop: 6,
  insetRight: 8,
  insetBottom: 6
};

function getAvatarRectAt(nx, ny) {
  if (!avatar) return null;

  const transformed = avatar.getTransformedBounds ? avatar.getTransformedBounds() : null;
  if (transformed) {
    const dx = nx - avatar.x;
    const dy = ny - avatar.y;
    return {
      x: transformed.x + dx + avatarHitbox.insetLeft,
      y: transformed.y + dy + avatarHitbox.insetTop,
      width: Math.max(1, transformed.width - avatarHitbox.insetLeft - avatarHitbox.insetRight),
      height: Math.max(1, transformed.height - avatarHitbox.insetTop - avatarHitbox.insetBottom)
    };
  }

  const bounds = avatar.getBounds ? avatar.getBounds() : null;
  if (bounds) {
    return {
      x: nx + bounds.x + avatarHitbox.insetLeft,
      y: ny + bounds.y + avatarHitbox.insetTop,
      width: Math.max(1, bounds.width - avatarHitbox.insetLeft - avatarHitbox.insetRight),
      height: Math.max(1, bounds.height - avatarHitbox.insetTop - avatarHitbox.insetBottom)
    };
  }

  return {
    x: nx + avatarHitbox.insetLeft,
    y: ny + avatarHitbox.insetTop,
    width: 20,
    height: 20
  };
}

function getDisplayObjectGlobalPosition(obj, x, y) {
  if (!obj) return null;
  if (obj.parent?.localToGlobal) return obj.parent.localToGlobal(x, y);
  if (obj.localToGlobal) return obj.localToGlobal(0, 0);
  return { x, y };
}

function getAvatarGlobalRectAt(nx, ny) {
  if (!avatar) return null;

  const rect = getGlobalDisplayRect(avatar);
  if (!rect) return getAvatarRectAt(nx, ny);

  const currentPoint = getDisplayObjectGlobalPosition(avatar, avatar.x, avatar.y);
  const targetPoint = getDisplayObjectGlobalPosition(avatar, nx, ny);
  const dx = currentPoint && targetPoint ? targetPoint.x - currentPoint.x : nx - avatar.x;
  const dy = currentPoint && targetPoint ? targetPoint.y - currentPoint.y : ny - avatar.y;

  return {
    x: rect.x + dx + avatarHitbox.insetLeft,
    y: rect.y + dy + avatarHitbox.insetTop,
    width: Math.max(1, rect.width - avatarHitbox.insetLeft - avatarHitbox.insetRight),
    height: Math.max(1, rect.height - avatarHitbox.insetTop - avatarHitbox.insetBottom)
  };
}

function collectWallInstances(container, results, seen) {
  if (!container || !container.children) return;

  container.children.forEach(child => {
    if (!child || seen.has(child)) return;
    seen.add(child);

    if (child.name && /^wall\d+$/i.test(child.name)) {
      results.push(child);
    }

    if (child.children && child.children.length) {
      collectWallInstances(child, results, seen);
    }
  });
}

function getWallBoundsFromInstance(instance) {
  if (!instance) return null;

  const transformed = instance.getTransformedBounds ? instance.getTransformedBounds() : null;
  if (transformed) {
    return {
      id: instance._wallId || instance.name || "(unknown wall)",
      x: transformed.x,
      y: transformed.y,
      w: transformed.width,
      h: transformed.height
    };
  }

  const bounds = instance.getBounds ? instance.getBounds() : null;
  if (bounds) {
    return {
      id: instance._wallId || instance.name || "(unknown wall)",
      x: instance.x + bounds.x,
      y: instance.y + bounds.y,
      w: bounds.width,
      h: bounds.height
    };
  }

  return null;
}

function buildWallData() {
  const wallInstances = [];
  const seen = new Set();

  Object.keys(this).forEach(key => {
    const item = this[key];
    if (item && /^wall\d+$/i.test(key) && !seen.has(item)) {
      item._wallId = key;
      seen.add(item);
      wallInstances.push(item);
    }
  });

  collectWallInstances(this, wallInstances, seen);

  wallData = wallInstances
    .map(getWallBoundsFromInstance)
    .filter(Boolean)
    .sort((a, b) => {
      const aNum = parseInt(String(a.id).replace(/\D+/g, ""), 10) || 0;
      const bNum = parseInt(String(b.id).replace(/\D+/g, ""), 10) || 0;
      return aNum - bNum;
    });
}

function getWallRect(wall) {
  return {
    x: wall.x - wallPadding,
    y: wall.y - wallPadding,
    width: wall.w + wallPadding * 2,
    height: wall.h + wallPadding * 2
  };
}

function rectsOverlap(a, b) {
  return (
    a.x < b.x + b.width &&
    a.x + a.width > b.x &&
    a.y < b.y + b.height &&
    a.y + a.height > b.y
  );
}

function isCollidingWithAnyWall(nx, ny) {
  const avatarRect = getAvatarRectAt(nx, ny);
  if (!avatarRect) return false;

  for (let i = 0; i < wallData.length; i++) {
    const wallRect = getWallRect(wallData[i]);
    if (rectsOverlap(avatarRect, wallRect)) {
      return true;
    }
  }

  return false;
}

// ====================== CHECKPOINT OVERLAP ======================
function getRect(obj) {
  if (!obj) return null;
  const tb = obj.getTransformedBounds ? obj.getTransformedBounds() : null;
  if (tb) return tb;
  const b = obj.getBounds ? obj.getBounds() : null;
  const w = obj.hitW || (b ? b.width  : 40);
  const h = obj.hitH || (b ? b.height : 40);
  return { x: obj.x, y: obj.y, width: w, height: h };
}

function objectsOverlap(a, b) {
  if (!a || !b) return false;
  const ar = getRect(a);
  const br = getRect(b);
  if (!ar || !br) return false;
  const acx = ar.x + ar.width  / 2;
  const acy = ar.y + ar.height / 2;
  const bcx = br.x + br.width  / 2;
  const bcy = br.y + br.height / 2;
  const threshold = Math.min(ar.width, ar.height, br.width, br.height) * 0.55;
  return Math.sqrt(Math.pow(acx - bcx, 2) + Math.pow(acy - bcy, 2)) < threshold;
}

function getGlobalDisplayRect(obj) {
  if (!obj) return null;

  const bounds = obj.getBounds ? obj.getBounds() : null;
  if (bounds && obj.localToGlobal) {
    const p1 = obj.localToGlobal(bounds.x, bounds.y);
    const p2 = obj.localToGlobal(bounds.x + bounds.width, bounds.y);
    const p3 = obj.localToGlobal(bounds.x + bounds.width, bounds.y + bounds.height);
    const p4 = obj.localToGlobal(bounds.x, bounds.y + bounds.height);
    const xs = [p1.x, p2.x, p3.x, p4.x];
    const ys = [p1.y, p2.y, p3.y, p4.y];
    return {
      x: Math.min(...xs),
      y: Math.min(...ys),
      width: Math.max(...xs) - Math.min(...xs),
      height: Math.max(...ys) - Math.min(...ys)
    };
  }

  if (obj.children && obj.children.length) {
    const childRects = obj.children
      .filter(child => child && child.visible !== false)
      .map(getGlobalDisplayRect)
      .filter(Boolean);

    if (childRects.length) {
      const minX = Math.min(...childRects.map(rect => rect.x));
      const minY = Math.min(...childRects.map(rect => rect.y));
      const maxX = Math.max(...childRects.map(rect => rect.x + rect.width));
      const maxY = Math.max(...childRects.map(rect => rect.y + rect.height));
      return { x: minX, y: minY, width: maxX - minX, height: maxY - minY };
    }
  }

  const fallback = getRect(obj);
  if (fallback && obj.localToGlobal) {
    const point = obj.localToGlobal(0, 0);
    if (point) {
      return {
        x: point.x,
        y: point.y,
        width: fallback.width,
        height: fallback.height
      };
    }
  }

  const transformed = obj.getTransformedBounds ? obj.getTransformedBounds() : null;
  if (transformed) return transformed;

  return fallback;
}

function expandRect(rect, amount) {
  if (!rect) return null;
  return {
    x: rect.x - amount,
    y: rect.y - amount,
    width: rect.width + amount * 2,
    height: rect.height + amount * 2
  };
}

// ====================== CHECKPOINT STATE MANAGEMENT ======================
function setCheckpointStates() {
  checkpoints.forEach((cp, index) => {
    if (!cp.clip) return;
    if (answered.has(cp.id)) {
      cp.clip.alpha        = 0;
      cp.clip.visible      = false;
    } else if (index === currentCheckpointIndex) {
      cp.clip.alpha        = 1;
      cp.clip.visible      = true;
      cp.clip.mouseEnabled = true;
    } else {
      cp.clip.alpha        = 0.25;
      cp.clip.visible      = true;
      cp.clip.mouseEnabled = false;
      createjs.Tween.removeTweens(cp.clip);
    }
  });
  refreshCheckpointLabels();
}

function hideAllCheckpoints() {
  stopAllFlickering();
  checkpoints.forEach(cp => {
    if (!cp.clip) return;
    createjs.Tween.removeTweens(cp.clip);
    cp.clip.visible = false;
    cp.clip.alpha = 0;
    cp.clip.mouseEnabled = false;
  });
  refreshCheckpointLabels();
}

// ====================== START GAME ======================
function startGame() {
  buildQuestionRun();
  gameState              = "PLAYING";
  currentCheckpointIndex = 0;
  elapsedTime            = 0;
  lives                  = STARTING_LIVES;
  grieverContactLocked   = false;
  answerFeedbackResetting = false;
  score                  = 0;
  answered.clear();
  lastTriggeredCP    = null;
  checkpointCooldown = false;

  if (failedScreen)  failedScreen.visible  = false;
  if (questionPanel) questionPanel.visible = false;
  hideCongratulations();
  updateTimeDisplay();
  updateScoreDisplay();
  updateLivesDisplay();

  hideWinScene();
  hideAllCheckpoints();
  resetGrievers();
  startTimer();

  showQuestion(0, checkpoints[0]?.id || "cp1");
}

window.startMazeChaseGame = startGame;

// ====================== RESET GAME ======================
function resetGame() {
  gameState = "INTRO";
  if (timerInterval) clearInterval(timerInterval);
  if (moveInterval)  clearInterval(moveInterval);
  stopQuestionAudio();
  clearAnswerBallLabels();
  lives = STARTING_LIVES;
  elapsedTime = 0;
  grieverContactLocked = false;
  answerFeedbackResetting = false;
  updateTimeDisplay();
  updateScoreDisplay();
  updateLivesDisplay();
  stopAllFlickering();
  resetGrievers();

  if (failedScreen)  failedScreen.visible  = false;
  if (questionPanel) questionPanel.visible = false;

  hideWinScene();
  restoreGameplayUi();

  if (avatar) {
    avatar.x = AVATAR_START_X; avatar.y = AVATAR_START_Y;
    avatar.alpha = 1; avatar.visible = true;
  }

  checkpoints.forEach(cp => {
    if (cp.clip) {
      cp.clip.alpha = 0; cp.clip.visible = false;
      cp.clip.mouseEnabled = false;
      cp.clip.scaleX = 1; cp.clip.scaleY = 1;
      createjs.Tween.removeTweens(cp.clip);
    }
  });

}

function restartGame() {
  try {
    const player = window.parent && window.parent.GetPlayer && window.parent.GetPlayer();
    if (player && player.SetVar) player.SetVar("startMaze", true);
  } catch (err) {}
  resetGame();
  startGame();
}

window.restartMazeChaseGame = restartGame;

function bindRestartButtons() {
  const seen = new Set();
  const buttons = [];

  function add(btn) {
    if (!btn || seen.has(btn)) return;
    seen.add(btn);
    buttons.push(btn);
  }

  add(failedScreen && (failedScreen.restartBtn || failedScreen.restartbtn));
  add(stageRoot.restartBtn);
  add(stageRoot.restartbtn);
  add(stageRoot.playAgainBtn);
  add(typeof getCongratulationClip === "function" && getCongratulationClip()
    ? getCongratulationClip().playAgainBtn
    : null);
  add(typeof getPeriodictable2RestartButton === "function" ? getPeriodictable2RestartButton() : null);

  if (typeof collectClipsByName === "function") {
    collectClipsByName(/restart/i).forEach(add);
  }

  buttons.forEach(btn => {
    btn.visible = true;
    btn.alpha = 1;
    btn.mouseEnabled = true;
    if (btn.removeAllEventListeners) btn.removeAllEventListeners("click");
    btn.addEventListener("click", restartGame);
  });
}

// ====================== TIMER ======================
function startTimer() {
  if (timerInterval) clearInterval(timerInterval);
  timerInterval = setInterval(() => {
    if (gameState !== "PLAYING" && gameState !== "QUESTION") return;
    elapsedTime++;
    updateTimeDisplay();
  }, 1000);
}

function formatTime(seconds) {
  seconds = Math.max(0, seconds);
  const min = Math.floor(seconds / 60);
  const sec = seconds % 60;
  return `${min}:${sec < 10 ? "0" : ""}${sec}`;
}

function setDisplayText(target, text) {
  if (!target) return false;

  if (target.text !== undefined) {
    target.text = text;
    return true;
  }

  if (target.children && target.children.length) {
    for (let i = 0; i < target.children.length; i++) {
      if (setDisplayText(target.children[i], text)) return true;
    }
  }

  return false;
}

function updateTimeDisplay() {
  const text = formatTime(elapsedTime);
  setDisplayText(timerText, text);
  setDisplayText(timeTakenText, text);
  setDisplayText(getFirstAvailableClip(["finalTimeText", "timeDisplay"]), "Time: " + text);
}

function updateScoreDisplay() {
  setDisplayText(scoreText, String(score));
  setDisplayText(getFirstAvailableClip(["finalScoreText", "scoreDisplay"]), "Score: " + score);
}

function loseLife(reason, deferGameOver = false) {
  if (gameState === "GAMEOVER" || gameState === "WIN") return;
  lives = Math.max(0, lives - 1);
  updateLivesDisplay();
  if (lives <= 0 && !deferGameOver) {
    triggerFailed(reason || "No lives left");
  }
}

function shakeDisplayObject(obj, duration = 520, strength = 7) {
  if (!obj) return;
  const startX = obj.x;
  const startY = obj.y;
  createjs.Tween.removeTweens(obj);
  createjs.Tween.get(obj)
    .to({ x: startX - strength, y: startY + 2 }, 55)
    .to({ x: startX + strength, y: startY - 2 }, 55)
    .to({ x: startX - strength * 0.75, y: startY - 1 }, 55)
    .to({ x: startX + strength * 0.75, y: startY + 1 }, 55)
    .to({ x: startX - strength * 0.45, y: startY + 1 }, 55)
    .to({ x: startX + strength * 0.45, y: startY - 1 }, 55)
    .to({ x: startX, y: startY }, Math.max(80, duration - 330), createjs.Ease.sineOut);
}

function returnAvatarToStart(animated = true, onComplete = null) {
  if (!avatar) {
    if (onComplete) onComplete();
    return;
  }

  createjs.Tween.removeTweens(avatar);
  avatar.visible = true;
  avatar.alpha = 1;

  if (!animated) {
    avatar.x = AVATAR_START_X;
    avatar.y = AVATAR_START_Y;
    avatar.scaleX = AVATAR_START_SCALE_X;
    avatar.scaleY = AVATAR_START_SCALE_Y;
    if (onComplete) onComplete();
    return;
  }

  createjs.Tween.get(avatar)
    .to({ scaleX: AVATAR_START_SCALE_X * 1.12, scaleY: AVATAR_START_SCALE_Y * 1.12, alpha: 0.78 }, 120, createjs.Ease.sineOut)
    .to({ x: AVATAR_START_X, y: AVATAR_START_Y, scaleX: AVATAR_START_SCALE_X * 0.92, scaleY: AVATAR_START_SCALE_Y * 0.92 }, AVATAR_RETURN_MS, createjs.Ease.quadInOut)
    .to({ scaleX: AVATAR_START_SCALE_X, scaleY: AVATAR_START_SCALE_Y, alpha: 1 }, 180, createjs.Ease.backOut)
    .call(() => {
      if (onComplete) onComplete();
    });
}

function beginAnswerFeedbackReset() {
  stopMoving();
  answerFeedbackResetting = true;
  grieverContactLocked = true;
  resetGrievers();
}

function endAnswerFeedbackReset(animateAvatar = true, onComplete = null) {
  resetGrievers();
  returnAvatarToStart(animateAvatar, () => {
    answerFeedbackResetting = false;
    grieverContactLocked = false;
    if (onComplete) onComplete();
  });
}

function handleGrieverContact(griever) {
  if (grieverContactLocked || gameState === "GAMEOVER" || gameState === "WIN") return;
  grieverContactLocked = true;
  stopMoving();
  shakeDisplayObject(avatar, 560, 8);
  shakeDisplayObject(griever, 560, 8);
  loseLife("Caught by a griever");

  if (lives > 0) {
    setTimeout(() => {
      if (avatar) {
        avatar.x = AVATAR_START_X;
        avatar.y = AVATAR_START_Y;
      }
      resetGrievers();
      grieverContactLocked = false;
    }, 720);
  }
}

function findLivesAnchor() {
  return getFirstAvailableClip(["hearts", "heart", "lives", "life", "livesText", "heartText"]);
}

function createHeartShape(size) {
  const heart = new createjs.Shape();
  heart.graphics
    .beginFill("#B7E4C7")
    .moveTo(size / 2, size * 0.9)
    .bezierCurveTo(size * -0.08, size * 0.48, size * 0.08, size * 0.08, size * 0.34, size * 0.18)
    .bezierCurveTo(size * 0.44, size * -0.02, size * 0.68, size * -0.02, size * 0.78, size * 0.18)
    .bezierCurveTo(size * 1.04, size * 0.08, size * 1.18, size * 0.48, size / 2, size * 0.9)
    .endFill();
  heart.shadow = new createjs.Shadow("rgba(0,0,0,0.45)", 0, 2, 4);
  return heart;
}

function ensureLivesDisplay() {
  if (livesContainer) return;

  const anchor = findLivesAnchor();
  livesContainer = new createjs.Container();
  livesContainer.name = "livesHearts";
  livesContainer.x = anchor ? anchor.x : 22;
  livesContainer.y = (anchor ? anchor.y : 22) + 35;

  if (anchor) {
    anchor.visible = false;
    const parent = anchor.parent || stageRoot;
    parent.addChild(livesContainer);
  } else {
    stageRoot.addChild(livesContainer);
  }

  lifeHearts = [];
  for (let i = 0; i < STARTING_LIVES; i++) {
    const heart = createHeartShape(26);
    heart.x = i * 34;
    heart.y = 0;
    livesContainer.addChild(heart);
    lifeHearts.push(heart);
  }
}

function getLifeHeartColor() {
  return "#B7E4C7";
}

function updateLivesDisplay() {
  ensureLivesDisplay();
  const color = getLifeHeartColor();

  lifeHearts.forEach((heart, index) => {
    heart.visible = true;
    heart.alpha = index < lives ? 1 : 0;
    heart.graphics
      .clear()
      .beginFill(color)
      .moveTo(13, 23.4)
      .bezierCurveTo(-2.08, 12.48, 2.08, 2.08, 8.84, 4.68)
      .bezierCurveTo(11.44, -0.52, 17.68, -0.52, 20.28, 4.68)
      .bezierCurveTo(27.04, 2.08, 30.68, 12.48, 13, 23.4)
      .endFill();
  });
}

// ====================== UNIFIED FAIL HANDLER ======================
function triggerFailed(reason) {
  if (gameState === "GAMEOVER") return;
  gameState = "GAMEOVER";
  if (timerInterval) clearInterval(timerInterval);
  if (moveInterval)  clearInterval(moveInterval);
  stopQuestionAudio();
  clearAnswerBallLabels();
  if (questionPanel) questionPanel.visible = false;

  if (failedScreen) {
    failedScreen.alpha   = 1;
    failedScreen.visible = true;
  }

  bindRestartButtons();
}

// ====================== GRIEVER CHASE ======================
function collectClipsByName(pattern) {
  const results = [];
  const resultSeen = new Set();

  Object.keys(stageRoot).forEach(key => {
    const clip = stageRoot[key];
    if (!clip || resultSeen.has(clip)) return;
    const name = String(clip.name || key || "");
    if (pattern.test(name)) {
      resultSeen.add(clip);
      results.push(clip);
    }
  });

  const descendants = [];
  collectNamedDescendants(stageRoot, descendants, new Set());
  descendants.forEach(clip => {
    if (!clip || resultSeen.has(clip)) return;
    const name = String(clip.name || "");
    if (pattern.test(name)) {
      resultSeen.add(clip);
      results.push(clip);
    }
  });

  return results;
}

function setupGrievers() {
  const disabledGriever = stageRoot.griever2;
  if (disabledGriever) {
    disabledGriever.visible = false;
    disabledGriever.alpha = 0;
    disabledGriever.mouseEnabled = false;
  }

  grievers = ["griever1", "griever3", "griever4"]
    .map(name => stageRoot[name])
    .filter(Boolean);

  if (!grievers.length) {
    grievers = collectClipsByName(/griever/i)
      .filter(griever => String(griever?.name || "").toLowerCase() !== "griever2");
  }

  grieverStartStates = grievers.map(griever => ({
    clip: griever,
    x: griever.x,
    y: griever.y,
    visible: griever.visible,
    alpha: griever.alpha
  }));

  boundaryObstacles = collectClipsByName(/boundary|triangle/i)
    .filter(clip => !grievers.includes(clip) && clip !== avatar);

  buildGrieverPathData();
  resetGrievers();
}

function resetGrievers() {
  grieverStartStates.forEach(state => {
    if (!state.clip) return;
    createjs.Tween.removeTweens(state.clip);
    state.clip.x = state.x;
    state.clip.y = state.y;
    state.clip.visible = state.visible !== false;
    state.clip.alpha = state.alpha == null ? 1 : state.alpha;
  });
  grieverPathStates = new WeakMap();
  clearGrieverCollisionCooldowns();
  assignGrieverBehaviors();
}

function clearGrieverCollisionCooldowns() {
  grievers.forEach(griever => {
    if (griever) {
      grieverCollisionCooldowns.delete(griever);
      grieverYieldTicks.delete(griever);
    }
  });
}

// ====================== FIXED: buildGrieverPathData ======================
function buildGrieverPathData() {
  const pathClips = [];
  const seen = new Set();

  // Collect p1...p35 directly from timeline properties
  for (let i = 1; i <= 35; i++) {
    const key = "p" + i;
    const clip = stageRoot[key];
    if (clip && !seen.has(clip)) {
      clip._pathId = key;
      seen.add(clip);
      pathClips.push(clip);
    }
  }

  // Also sweep named descendants in case paths are nested
  const descendants = [];
  collectNamedDescendants(stageRoot, descendants, new Set());
  descendants.forEach(clip => {
    if (!clip || seen.has(clip)) return;
    if (/^p\d+$/i.test(String(clip.name || ""))) {
      clip._pathId = clip.name;
      seen.add(clip);
      pathClips.push(clip);
    }
  });

  grieverPaths = pathClips
    .map(clip => {
      let rect = null;

      // 1. Full global transform (best — accounts for parent scaling/rotation)
      const gb = clip.getTransformedBounds ? clip.getTransformedBounds() : null;
      if (gb && gb.width > 0 && gb.height > 0) {
        rect = { x: gb.x, y: gb.y, width: gb.width, height: gb.height };
      }

      // 2. Local bounds + clip position (works when parents are identity transforms)
      if (!rect) {
        const lb = clip.getBounds ? clip.getBounds() : null;
        if (lb && lb.width > 0 && lb.height > 0) {
          rect = { x: clip.x + lb.x, y: clip.y + lb.y,
                   width: lb.width, height: lb.height };
        }
      }

      // 3. Last resort: use clip.x/y with hitW/hitH or a default size
      if (!rect) {
        const w = clip.hitW || clip.width || 40;
        const h = clip.hitH || clip.height || 40;
        rect = { x: clip.x, y: clip.y, width: w, height: h };
      }

      if (!rect || rect.width <= 0 || rect.height <= 0) {
        return null;
      }

      return {
        id:   clip._pathId || clip.name || "(unnamed path)",
        clip,
        rect,
        axis: rect.width >= rect.height ? "x" : "y"
      };
    })
    .filter(Boolean)
    .sort((a, b) => {
      const aNum = parseInt(String(a.id).replace(/\D+/g, ""), 10) || 0;
      const bNum = parseInt(String(b.id).replace(/\D+/g, ""), 10) || 0;
      return aNum - bNum;
    });
}

function pointInRect(point, rect, pad = 0) {
  return !!point && !!rect &&
    point.x >= rect.x - pad &&
    point.x <= rect.x + rect.width + pad &&
    point.y >= rect.y - pad &&
    point.y <= rect.y + rect.height + pad;
}

function getObjectCenter(obj) {
  const rect = getRect(obj);
  if (!rect) return { x: obj?.x || 0, y: obj?.y || 0 };
  return {
    x: rect.x + rect.width / 2,
    y: rect.y + rect.height / 2
  };
}

function getGrieverRectAt(griever, nx, ny) {
  const rect = getRect(griever);
  if (!rect) return null;
  return {
    x: rect.x + (nx - griever.x),
    y: rect.y + (ny - griever.y),
    width: rect.width,
    height: rect.height
  };
}

function shrinkRect(rect, amount) {
  if (!rect) return null;
  return {
    x: rect.x + amount,
    y: rect.y + amount,
    width: Math.max(1, rect.width - amount * 2),
    height: Math.max(1, rect.height - amount * 2)
  };
}

function getGrieverCollisionRectAt(griever, nx, ny) {
  return shrinkRect(getGrieverRectAt(griever, nx, ny), 3);
}

function getBlockingGrieverAt(griever, nx, ny) {
  const grieverRect = getGrieverCollisionRectAt(griever, nx, ny);
  if (!grieverRect) return null;

  for (let i = 0; i < grievers.length; i++) {
    const other = grievers[i];
    if (!other || other === griever || other.visible === false) continue;
    const otherRect = getGrieverCollisionRectAt(other, other.x, other.y);
    if (otherRect && rectsOverlap(grieverRect, otherRect)) return other;
  }

  return null;
}

function reversePathState(state, fromCollision = false) {
  if (!state) return;
  state.direction *= -1;
  state.samePathReversals = (state.samePathReversals || 0) + 1;
  if (state.samePathReversals >= GRIEVER_SAME_PATH_REVERSAL_LIMIT) {
    state.forceDiversion = true;
  }
  if (fromCollision) {
    state.collisionRetreatTicks = GRIEVER_COLLISION_RETREAT_TICKS;
    state.forcedReturnPath = state.previousPath || state.lastPath || null;
  }
}

function reverseGrieverDirection(griever) {
  if (!griever) return;

  const tick = createjs.Ticker?.getTicks ? createjs.Ticker.getTicks() : Date.now();
  if (grieverReverseTicks.get(griever) === tick) return;
  grieverReverseTicks.set(griever, tick);

  const state = grieverPathStates.get(griever);
  if (state) {
    reversePathState(state, true);
  }

  const direction = grieverDirections.get(griever);
  if (direction) {
    direction.x *= -1;
    direction.y *= -1;
    direction.turnsUntilChange = Math.max(direction.turnsUntilChange || 0, 12);
    direction.collisionRetreatTicks = GRIEVER_COLLISION_RETREAT_TICKS;
  }
}

function canPlaceGrieverIgnoringPeers(griever, nx, ny) {
  const grieverRect = getGrieverCollisionRectAt(griever, nx, ny);
  if (!grieverRect) return false;

  for (let i = 0; i < wallData.length; i++) {
    if (rectsOverlap(grieverRect, getWallRect(wallData[i]))) return false;
  }
  for (let i = 0; i < boundaryObstacles.length; i++) {
    const obstacleRect = getRect(boundaryObstacles[i]);
    if (obstacleRect && rectsOverlap(grieverRect, obstacleRect)) return false;
  }
  return true;
}

function separateCollidingGrievers(a, b) {
  if (!a || !b) return;
  const aCenter = getObjectCenter(a);
  const bCenter = getObjectCenter(b);
  let dx = bCenter.x - aCenter.x;
  let dy = bCenter.y - aCenter.y;
  let distance = Math.sqrt(dx * dx + dy * dy);
  if (distance < 0.01) {
    const angle = Math.random() * Math.PI * 2;
    dx = Math.cos(angle);
    dy = Math.sin(angle);
    distance = 1;
  }
  const ux = dx / distance;
  const uy = dy / distance;

  for (let step = 0; step < GRIEVER_PUSH_STEPS; step++) {
    const aX = a.x - ux * GRIEVER_COLLISION_SEPARATION;
    const aY = a.y - uy * GRIEVER_COLLISION_SEPARATION;
    const bX = b.x + ux * GRIEVER_COLLISION_SEPARATION;
    const bY = b.y + uy * GRIEVER_COLLISION_SEPARATION;
    if (canPlaceGrieverIgnoringPeers(a, aX, aY)) {
      a.x = aX;
      a.y = aY;
    }
    if (canPlaceGrieverIgnoringPeers(b, bX, bY)) {
      b.x = bX;
      b.y = bY;
    }
    if (!grieversCurrentlyOverlap(a, b)) break;
  }
}

function getGrieverCollisionCooldown(griever) {
  return grieverCollisionCooldowns.get(griever) || 0;
}

function setGrieverCollisionCooldown(griever) {
  if (griever) grieverCollisionCooldowns.set(griever, GRIEVER_COLLISION_COOLDOWN_TICKS);
}

function tickGrieverCollisionCooldowns() {
  grievers.forEach(griever => {
    const ticks = getGrieverCollisionCooldown(griever);
    if (ticks > 1) grieverCollisionCooldowns.set(griever, ticks - 1);
    else if (ticks === 1) grieverCollisionCooldowns.delete(griever);

    const yieldTicks = grieverYieldTicks.get(griever) || 0;
    if (yieldTicks > 1) grieverYieldTicks.set(griever, yieldTicks - 1);
    else if (yieldTicks === 1) grieverYieldTicks.delete(griever);
  });
}

function setGrieverYield(griever, ticks = GRIEVER_COLLISION_YIELD_TICKS) {
  if (!griever) return;
  grieverYieldTicks.set(griever, ticks);
}

function handleGrieverSoftWallCollision(griever, other) {
  if (!griever || !other) return false;

  if (getGrieverCollisionCooldown(griever) > 0 || getGrieverCollisionCooldown(other) > 0) {
    return false;
  }

  reverseGrieverDirection(griever);
  reverseGrieverDirection(other);
  const movingState = grieverPathStates.get(griever);
  const otherState = grieverPathStates.get(other);
  if (movingState) movingState.pauseTicks = 0;
  if (otherState) otherState.pauseTicks = 0;
  separateCollidingGrievers(griever, other);
  setGrieverCollisionCooldown(griever);
  setGrieverCollisionCooldown(other);
  return false;
}

function grieversCurrentlyOverlap(a, b) {
  if (!a || !b || a.visible === false || b.visible === false) return false;
  const aRect = getGrieverCollisionRectAt(a, a.x, a.y);
  const bRect = getGrieverCollisionRectAt(b, b.x, b.y);
  return !!aRect && !!bRect && rectsOverlap(aRect, bRect);
}

function resolveCurrentGrieverClumps() {
  for (let i = 0; i < grievers.length; i++) {
    for (let j = i + 1; j < grievers.length; j++) {
      const a = grievers[i];
      const b = grievers[j];
      if (grieversCurrentlyOverlap(a, b)) {
        handleGrieverSoftWallCollision(a, b);
      }
    }
  }
}

function isGrieverBlocked(griever, nx, ny) {
  const grieverRect = getGrieverCollisionRectAt(griever, nx, ny);
  if (!grieverRect) return false;

  for (let i = 0; i < wallData.length; i++) {
    if (rectsOverlap(grieverRect, getWallRect(wallData[i]))) return true;
  }

  for (let i = 0; i < boundaryObstacles.length; i++) {
    const obstacleRect = getRect(boundaryObstacles[i]);
    if (obstacleRect && rectsOverlap(grieverRect, obstacleRect)) return true;
  }

  if (getBlockingGrieverAt(griever, nx, ny)) return true;

  return false;
}

const GRIEVER_MOVE_DIRECTIONS = [
  { x: 1, y: 0 },
  { x: -1, y: 0 },
  { x: 0, y: 1 },
  { x: 0, y: -1 },
  { x: 0.707, y: 0.707 },
  { x: -0.707, y: 0.707 },
  { x: 0.707, y: -0.707 },
  { x: -0.707, y: -0.707 }
];

function assignGrieverBehaviors() {
  grievers.forEach((griever, index) => {
    if (!griever) return;
    grieverModes.set(griever, grieverPaths.length ? "path" : "wander");
    if (grieverPaths.length && !grieverPathStates.has(griever)) {
      const pathState = createGrieverPathState(griever);
      if (pathState) grieverPathStates.set(griever, pathState);
    }
    if (!grieverPaths.length && !grieverDirections.has(griever)) {
      pickRandomGrieverDirection(griever);
    }
  });
}

function getOpenGrieverDirections(griever, speed) {
  return GRIEVER_MOVE_DIRECTIONS.filter(dir => {
    return !isGrieverBlocked(griever, griever.x + dir.x * speed, griever.y + dir.y * speed);
  });
}

function pickRandomGrieverDirection(griever) {
  const openDirections = getOpenGrieverDirections(griever, GRIEVER_RANDOM_SPEED);
  const choices = openDirections.length ? openDirections : GRIEVER_MOVE_DIRECTIONS;
  const direction = choices[Math.floor(Math.random() * choices.length)];
  grieverDirections.set(griever, {
    x: direction.x,
    y: direction.y,
    turnsUntilChange: 24 + Math.floor(Math.random() * 54)
  });
}

function pushGrieverAwayFromWall(griever) {
  const openDirections = getOpenGrieverDirections(griever, GRIEVER_PUSH_DISTANCE);
  if (!openDirections.length) return false;

  const direction = openDirections[Math.floor(Math.random() * openDirections.length)];
  grieverDirections.set(griever, {
    x: direction.x,
    y: direction.y,
    turnsUntilChange: 20 + Math.floor(Math.random() * 45)
  });
  return true;
}

function moveGrieverByVector(griever, stepX, stepY) {
  const nextX = griever.x + stepX;
  const nextY = griever.y + stepY;
  const blockingGriever = getBlockingGrieverAt(griever, nextX, nextY);

  if (blockingGriever) {
    return handleGrieverSoftWallCollision(griever, blockingGriever);
  }

  if (!isGrieverBlocked(griever, nextX, nextY)) {
    griever.x = nextX;
    griever.y = nextY;
    return true;
  }

  let moved = false;
  const xBlockingGriever = getBlockingGrieverAt(griever, nextX, griever.y);
  if (xBlockingGriever) {
    return handleGrieverSoftWallCollision(griever, xBlockingGriever);
  }
  if (!isGrieverBlocked(griever, nextX, griever.y)) {
    griever.x = nextX;
    moved = true;
  }
  const yBlockingGriever = getBlockingGrieverAt(griever, griever.x, nextY);
  if (yBlockingGriever) {
    return handleGrieverSoftWallCollision(griever, yBlockingGriever);
  }
  if (!isGrieverBlocked(griever, griever.x, nextY)) {
    griever.y = nextY;
    moved = true;
  }

  if (!moved) {
    const direction = grieverDirections.get(griever);
    if (direction) {
      direction.x *= -1;
      direction.y *= -1;
      direction.turnsUntilChange = Math.max(direction.turnsUntilChange || 0, 18);
    } else {
      pickRandomGrieverDirection(griever);
    }
  }
  return moved;
}

function moveGrieverByVectorGracefully(griever, stepX, stepY, onBlockedByGriever = null) {
  const nextX = griever.x + stepX;
  const nextY = griever.y + stepY;
  const blockingGriever = getBlockingGrieverAt(griever, nextX, nextY);

  if (blockingGriever) {
    if (onBlockedByGriever && onBlockedByGriever(blockingGriever)) return true;
    return handleGrieverSoftWallCollision(griever, blockingGriever);
  }

  if (!isGrieverBlocked(griever, nextX, nextY)) {
    griever.x = nextX;
    griever.y = nextY;
    return true;
  }

  return false;
}

function moveGrieverCenterTo(griever, center) {
  const currentCenter = getGrieverCenterAt(griever, griever.x, griever.y);
  const dx = center.x - currentCenter.x;
  const dy = center.y - currentCenter.y;
  if (dx * dx + dy * dy > GRIEVER_MAX_PATH_SNAP * GRIEVER_MAX_PATH_SNAP) return false;

  const nextX = griever.x + (center.x - currentCenter.x);
  const nextY = griever.y + (center.y - currentCenter.y);
  const blockingGriever = getBlockingGrieverAt(griever, nextX, nextY);

  if (blockingGriever) {
    return handleGrieverSoftWallCollision(griever, blockingGriever);
  }

  if (isGrieverBlocked(griever, nextX, nextY)) return false;

  griever.x = nextX;
  griever.y = nextY;
  return true;
}

function tryMoveGrieverInsidePath(griever, path, targetCenter) {
  if (!path || !targetCenter) return false;
  const center = clampPointToPath(targetCenter, path);
  return moveGrieverCenterTo(griever, center);
}

function getDistanceToPath(point, path) {
  if (!point || !path) return Infinity;
  const clamped = clampPointToPath(point, path);
  const dx = point.x - clamped.x;
  const dy = point.y - clamped.y;
  return dx * dx + dy * dy;
}

function getPathCenter(path) {
  if (!path?.rect) return { x: 0, y: 0 };
  return {
    x: path.rect.x + path.rect.width / 2,
    y: path.rect.y + path.rect.height / 2
  };
}

function getRectDistanceSq(a, b) {
  if (!a || !b) return Infinity;
  const dx = Math.max(a.x - (b.x + b.width), b.x - (a.x + a.width), 0);
  const dy = Math.max(a.y - (b.y + b.height), b.y - (a.y + a.height), 0);
  return dx * dx + dy * dy;
}

function getPathForwardPoint(path, direction) {
  const rect = path?.rect;
  if (!rect) return null;
  return path.axis === "x"
    ? {
        x: direction >= 0 ? rect.x + rect.width : rect.x,
        y: rect.y + rect.height / 2
      }
    : {
        x: rect.x + rect.width / 2,
        y: direction >= 0 ? rect.y + rect.height : rect.y
      };
}

function getPathMovementVector(state, currentCenter, speed) {
  if (!state?.path || !currentCenter) return { x: 0, y: 0 };

  const pathCenter = getPathCenter(state.path);
  if (state.path.axis === "x") {
    const correction = Math.max(
      -GRIEVER_CENTERING_SPEED,
      Math.min(GRIEVER_CENTERING_SPEED, pathCenter.y - currentCenter.y)
    );
    return { x: state.direction * speed, y: correction };
  }

  const correction = Math.max(
    -GRIEVER_CENTERING_SPEED,
    Math.min(GRIEVER_CENTERING_SPEED, pathCenter.x - currentCenter.x)
  );
  return { x: correction, y: state.direction * speed };
}

function getPathDirectionAwayFromPath(path, previousPath, fallbackPoint) {
  if (!path) return 1;
  const pathCenter = getPathCenter(path);
  const previousCenter = previousPath ? getPathCenter(previousPath) : fallbackPoint;
  const comparePoint = previousCenter || fallbackPoint || pathCenter;
  const delta = path.axis === "x"
    ? pathCenter.x - comparePoint.x
    : pathCenter.y - comparePoint.y;
  if (Math.abs(delta) > 1) return delta >= 0 ? 1 : -1;
  return Math.random() < 0.5 ? -1 : 1;
}

function rememberGrieverPath(state, path) {
  if (!state || !path) return;
  state.recentPaths = state.recentPaths || [];
  state.recentPaths = state.recentPaths.filter(item => item !== path);
  state.recentPaths.unshift(path);
  if (state.recentPaths.length > GRIEVER_RECENT_PATH_LIMIT) {
    state.recentPaths.length = GRIEVER_RECENT_PATH_LIMIT;
  }
}

function noteGrieverPathTransition(state, nextPath) {
  if (!state || !nextPath) return;
  if (state.lastPath && nextPath === state.lastPath && state.path === state.previousPath) {
    state.oscillationTurns = (state.oscillationTurns || 0) + 1;
  } else if (state.previousPath && nextPath === state.previousPath) {
    state.oscillationTurns = (state.oscillationTurns || 0) + 1;
  } else {
    state.oscillationTurns = 0;
  }
  state.samePathReversals = 0;
  state.lastPath = state.path;
}

function getOscillationDiversionPath(griever, state, targetCenter) {
  const needsDiversion = state?.forceDiversion ||
    (state?.oscillationTurns || 0) >= GRIEVER_OSCILLATION_LIMIT ||
    (state?.samePathReversals || 0) >= GRIEVER_SAME_PATH_REVERSAL_LIMIT;
  if (!state?.path || !needsDiversion) return null;

  const currentCenter = getGrieverCenterAt(griever, griever.x, griever.y);
  const allNeighbors = getPathNeighbors(state.path);
  const freshNeighbors = allNeighbors.filter(path =>
    path !== state.previousPath &&
    path !== state.lastPath &&
    !(state.recentPaths || []).includes(path)
  );
  const nonPreviousNeighbors = allNeighbors.filter(path => path !== state.previousPath);
  const pool = freshNeighbors.length
    ? freshNeighbors
    : (nonPreviousNeighbors.length ? nonPreviousNeighbors : allNeighbors);
  const neighbors = pool.sort((a, b) => {
      const target = targetCenter || currentCenter;
      const aTarget = getDistanceToPath(target, a);
      const bTarget = getDistanceToPath(target, b);
      if (aTarget !== bTarget) return aTarget - bTarget;
      return getDistanceToPath(currentCenter, a) - getDistanceToPath(currentCenter, b);
    });

  const shortlist = neighbors.slice(0, Math.min(2, neighbors.length));
  return shortlist.length ? shortlist[Math.floor(Math.random() * shortlist.length)] : null;
}

function pickPathCandidate(candidates, state) {
  if (!candidates.length) return null;

  const nonPrevious = candidates.filter(path => path !== state.previousPath);
  const pool = nonPrevious.length ? nonPrevious : candidates;

  const nonRecent = pool.filter(path => !(state.recentPaths || []).includes(path));
  const preferred = nonRecent.length ? nonRecent : pool;
  const shortlist = preferred.slice(0, Math.min(3, preferred.length));

  return shortlist[Math.floor(Math.random() * shortlist.length)];
}

function chooseNextPath(griever, state, targetCenter) {
  if (!state?.path) return null;

  const currentCenter = getGrieverCenterAt(griever, griever.x, griever.y);
  if (state.forcedReturnPath) {
    const returnPath = state.forcedReturnPath;
    const isNeighbor = getPathNeighbors(state.path).includes(returnPath);
    const returnCenter = clampPointToPath(currentCenter, returnPath);
    if (isNeighbor && tryMoveGrieverInsidePath(griever, returnPath, returnCenter)) {
      state.forcedReturnPath = null;
      state.collisionRetreatTicks = 0;
      return returnPath;
    }
    if (!isNeighbor) state.forcedReturnPath = null;
  }

  const diversionPath = getOscillationDiversionPath(griever, state, targetCenter);
  if (diversionPath) {
    const diversionCenter = clampPointToPath(currentCenter, diversionPath);
    if (tryMoveGrieverInsidePath(griever, diversionPath, diversionCenter)) {
      state.forceDiversion = false;
      state.oscillationTurns = 0;
      state.samePathReversals = 0;
      state.recentPaths = [diversionPath];
      return diversionPath;
    }
  }

  const forwardPoint = getPathForwardPoint(state.path, state.direction) || currentCenter;
  const neighbors = getPathNeighbors(state.path)
    .sort((a, b) => {
      const aForwardDistance = getDistanceToPath(forwardPoint, a);
      const bForwardDistance = getDistanceToPath(forwardPoint, b);
      if (aForwardDistance !== bForwardDistance) return aForwardDistance - bForwardDistance;
      const aTargetDistance = getDistanceToPath(targetCenter, a);
      const bTargetDistance = getDistanceToPath(targetCenter, b);
      if (aTargetDistance !== bTargetDistance) return aTargetDistance - bTargetDistance;
      const aDistance = getDistanceToPath(currentCenter, a);
      const bDistance = getDistanceToPath(currentCenter, b);
      return aDistance - bDistance;
    });

  if (!neighbors.length) return null;

  while (neighbors.length) {
    const nextPath = pickPathCandidate(neighbors, state);
    if (!nextPath) return null;
    const nextCenter = clampPointToPath(currentCenter, nextPath);
    if (tryMoveGrieverInsidePath(griever, nextPath, nextCenter)) {
      return nextPath;
    }
    neighbors.splice(neighbors.indexOf(nextPath), 1);
  }

  return null;
}

function recoverStuckPathGriever(griever, state, targetPoint) {
  if (!griever || !state?.path) return;

  const currentCenter = getGrieverCenterAt(griever, griever.x, griever.y);
  const neighbors = getPathNeighbors(state.path)
    .filter(path => path !== state.previousPath)
    .sort((a, b) => {
      const target = targetPoint || currentCenter;
      const aDistance = getDistanceToPath(target, a);
      const bDistance = getDistanceToPath(target, b);
      if (aDistance !== bDistance) return aDistance - bDistance;
      return getDistanceToPath(currentCenter, a) - getDistanceToPath(currentCenter, b);
    });

  while (neighbors.length) {
    const nextPath = neighbors.shift();
    const nextCenter = clampPointToPath(currentCenter, nextPath);
    if (tryMoveGrieverInsidePath(griever, nextPath, nextCenter)) {
      const previousPath = state.path;
      state.previousPath = previousPath;
      noteGrieverPathTransition(state, nextPath);
      state.path = nextPath;
      state.direction = getPathDirectionAwayFromPath(nextPath, previousPath, currentCenter);
      state.recentPaths = [nextPath];
      state.stuckTicks = 0;
      return;
    }
  }

  reversePathState(state);
  state.recentPaths = [state.path];
  state.stuckTicks = 0;
}

function trackPathGrieverProgress(griever, state, targetPoint) {
  if (!griever || !state) return;

  const lastX = state.lastX;
  const lastY = state.lastY;
  state.lastX = griever.x;
  state.lastY = griever.y;

  if (lastX == null || lastY == null) {
    state.stuckTicks = 0;
    return;
  }

  const dx = griever.x - lastX;
  const dy = griever.y - lastY;
  if (dx * dx + dy * dy >= GRIEVER_STUCK_MOVE_EPS * GRIEVER_STUCK_MOVE_EPS) {
    state.stuckTicks = 0;
    return;
  }

  state.stuckTicks = (state.stuckTicks || 0) + 1;
  if (state.stuckTicks >= GRIEVER_STUCK_TICKS) {
    recoverStuckPathGriever(griever, state, targetPoint);
    state.lastX = griever.x;
    state.lastY = griever.y;
  }
}

function updatePathGriever(griever, targetPoint) {
  let state = grieverPathStates.get(griever);
  if (!state) {
    state = createGrieverPathState(griever);
    if (!state) return null;
    grieverPathStates.set(griever, state);
  }

  if (state.pauseTicks > 0) {
    state.pauseTicks--;
    trackPathGrieverProgress(griever, state, targetPoint);
    return state;
  }

  const speed = targetPoint ? GRIEVER_SPEED : GRIEVER_RANDOM_SPEED;
  const currentCenter = getGrieverCenterAt(griever, griever.x, griever.y);

  if (!pointInRect(currentCenter, state.path.rect, GRIEVER_PATH_JOIN_PAD)) {
    const clampedCenter = clampPointToPath(currentCenter, state.path);
    const dx = clampedCenter.x - currentCenter.x;
    const dy = clampedCenter.y - currentCenter.y;
    const distance = Math.sqrt(dx * dx + dy * dy) || 1;
    if (moveGrieverByVectorGracefully(griever, (dx / distance) * speed, (dy / distance) * speed)) {
      if (state.collisionRetreatTicks > 0) state.collisionRetreatTicks--;
      trackPathGrieverProgress(griever, state, targetPoint);
      return state;
    }
    if (state.collisionRetreatTicks > 0) {
      state.collisionRetreatTicks--;
      trackPathGrieverProgress(griever, state, targetPoint);
      return state;
    }
    reversePathState(state);
    trackPathGrieverProgress(griever, state, targetPoint);
    return state;
  }

  const targetCenter = {
    x: currentCenter.x + (state.path.axis === "x" ? state.direction * speed : 0),
    y: currentCenter.y + (state.path.axis === "y" ? state.direction * speed : 0)
  };

  if (pointInRect(targetCenter, state.path.rect, 0)) {
    const moveVector = getPathMovementVector(state, currentCenter, speed);
    if (moveGrieverByVectorGracefully(
      griever,
      moveVector.x,
      moveVector.y
    )) {
      if (state.collisionRetreatTicks > 0) state.collisionRetreatTicks--;
      trackPathGrieverProgress(griever, state, targetPoint);
      return state;
    }

    if (state.collisionRetreatTicks > 0) {
      state.collisionRetreatTicks--;
      trackPathGrieverProgress(griever, state, targetPoint);
      return state;
    }

    const blockedNextPath = chooseNextPath(griever, state, targetPoint || targetCenter);
    if (blockedNextPath) {
      const previousPath = state.path;
      state.previousPath = previousPath;
      noteGrieverPathTransition(state, blockedNextPath);
      state.path = blockedNextPath;
      state.direction = getPathDirectionAwayFromPath(blockedNextPath, previousPath, currentCenter);
      rememberGrieverPath(state, blockedNextPath);
      trackPathGrieverProgress(griever, state, targetPoint);
      return state;
    }

    reversePathState(state);
    trackPathGrieverProgress(griever, state, targetPoint);
    return state;
  }

  const nextPath = chooseNextPath(griever, state, targetPoint || targetCenter);
  if (nextPath) {
    const previousPath = state.path;
    state.previousPath = previousPath;
    noteGrieverPathTransition(state, nextPath);
    state.path = nextPath;
    state.direction = getPathDirectionAwayFromPath(nextPath, previousPath, currentCenter);
    rememberGrieverPath(state, nextPath);
    trackPathGrieverProgress(griever, state, targetPoint);
    return state;
  }

  reversePathState(state);
  const reverseTarget = {
    x: currentCenter.x + (state.path.axis === "x" ? state.direction * speed : 0),
    y: currentCenter.y + (state.path.axis === "y" ? state.direction * speed : 0)
  };

  tryMoveGrieverInsidePath(griever, state.path, reverseTarget);

  trackPathGrieverProgress(griever, state, targetPoint);
  return state;
}

function updateChasingGriever(griever, avatarCenter) {
  const grieverCenter = getObjectCenter(griever);
  const dx = avatarCenter.x - grieverCenter.x;
  const dy = avatarCenter.y - grieverCenter.y;
  const distance = Math.sqrt(dx * dx + dy * dy) || 1;
  const moved = moveGrieverByVector(
    griever,
    (dx / distance) * GRIEVER_SPEED,
    (dy / distance) * GRIEVER_SPEED
  );

  if (!moved) pickRandomGrieverDirection(griever);
  return distance;
}

function updateWanderingGriever(griever) {
  let direction = grieverDirections.get(griever);
  const retreating = (direction?.collisionRetreatTicks || 0) > 0;
  if (!direction || (!retreating && (direction.turnsUntilChange <= 0 || Math.random() < 0.015))) {
    pickRandomGrieverDirection(griever);
    direction = grieverDirections.get(griever);
  }

  const moved = moveGrieverByVector(
    griever,
    direction.x * GRIEVER_RANDOM_SPEED,
    direction.y * GRIEVER_RANDOM_SPEED
  );

  if (moved) {
    direction.turnsUntilChange--;
    if (direction.collisionRetreatTicks > 0) direction.collisionRetreatTicks--;
  } else if (direction.collisionRetreatTicks > 0) {
    direction.collisionRetreatTicks--;
  } else {
    pickRandomGrieverDirection(griever);
  }

  return direction;
}

// ====================== SMART PATH CHASE ======================
// When a griever is within chase radius it continuously re-evaluates which
// path rectangle is closest to the avatar and snaps its state onto that path,
// then drives along it toward the avatar.  This makes grievers actively hunt
// the avatar through the maze network instead of wandering their current path.

function getNearestPathToAvatar(avatarCenter) {
  if (!grieverPaths.length || !avatarCenter) return null;
  let bestPath = null;
  let bestDist = Infinity;
  grieverPaths.forEach(path => {
    const clamped = clampPointToPath(avatarCenter, path);
    const dx = avatarCenter.x - clamped.x;
    const dy = avatarCenter.y - clamped.y;
    const d  = dx * dx + dy * dy;
    if (d < bestDist) { bestDist = d; bestPath = path; }
  });
  return bestPath;
}

// Ensures the griever's path state is steering toward the path rect nearest
// to the avatar. If the griever is already on an adjacent path it just
// updates direction; otherwise it migrates to the nearest reachable path
// that is closer to the avatar than the current one.
function snapGrieverTowardAvatar(griever, state, avatarCenter) {
  if (!state || !avatarCenter || !grieverPaths.length) return;

  const targetPath = getNearestPathToAvatar(avatarCenter);
  if (!targetPath || targetPath === state.path) {
    // Already on the best path — just aim direction toward avatar
    return;
  }

  // If the target path is a direct neighbour, steer toward it naturally
  const neighbors = getPathNeighbors(state.path);
  if (neighbors.includes(targetPath)) {
    return;
  }

  // Find the path nearest to the griever itself; if it is closer to the
  // avatar than the current path, switch onto it to close the gap
  const grieverCenter = getGrieverCenterAt(griever, griever.x, griever.y);
  const nearestToSelf = getNearestPathToPoint(grieverCenter);
  const currentNeighbors = getPathNeighbors(state.path);

  const recentlyVisited = state.recentPaths || [];
  if (nearestToSelf &&
      nearestToSelf !== state.path &&
      currentNeighbors.includes(nearestToSelf) &&
      nearestToSelf !== state.previousPath &&
      !recentlyVisited.includes(nearestToSelf)) {
    const distCurrent = getDistanceToPath(avatarCenter, state.path);
    const distNearest = getDistanceToPath(avatarCenter, nearestToSelf);
    if (distNearest < distCurrent) {
      const previousPath = state.path;
      state.previousPath = previousPath;
      noteGrieverPathTransition(state, nearestToSelf);
      state.path         = nearestToSelf;
      state.direction    = getPathDirectionAwayFromPath(nearestToSelf, previousPath, grieverCenter);
      rememberGrieverPath(state, nearestToSelf);
    }
  }
}

function updateGrievers() {
  if (answerFeedbackResetting) return;
  if ((gameState !== "PLAYING" && gameState !== "QUESTION") || !avatar) return;

  tickGrieverCollisionCooldowns();
  resolveCurrentGrieverClumps();
  const avatarCenter = getObjectCenter(avatar);

  grievers.forEach((griever, index) => {
    if (!griever || griever.visible === false) return;

    const grieverCenterBeforeMove = getObjectCenter(griever);
    const distanceBeforeMove = Math.sqrt(
      Math.pow(avatarCenter.x - grieverCenterBeforeMove.x, 2) +
      Math.pow(avatarCenter.y - grieverCenterBeforeMove.y, 2)
    ) || 1;

    const mode = grieverModes.get(griever) || (grieverPaths.length ? "path" : "wander");
    const isChasing = distanceBeforeMove <= GRIEVER_CHASE_RADIUS;

    if (isChasing && mode === "path") {
      // KEY: each tick, migrate the griever's active path to whichever
      // rectangle is nearest to the avatar so it hunts purposefully
      let state = grieverPathStates.get(griever);
      if (!state) {
        state = createGrieverPathState(griever);
        if (state) grieverPathStates.set(griever, state);
      }
      if (state) snapGrieverTowardAvatar(griever, state, avatarCenter);
      updatePathGriever(griever, avatarCenter);

    } else if (isChasing) {
      // No path data — fall back to direct vector chase
      updateChasingGriever(griever, avatarCenter);

    } else if (mode === "path") {
      // Outside chase radius — wander along paths normally
      updatePathGriever(griever);

    } else if (mode === "chase") {
      updateChasingGriever(griever, avatarCenter);

    } else {
      updateWanderingGriever(griever);
    }

    const grieverCenter = getObjectCenter(griever);
    const distance = Math.sqrt(
      Math.pow(avatarCenter.x - grieverCenter.x, 2) +
      Math.pow(avatarCenter.y - grieverCenter.y, 2)
    ) || 1;

    if (objectsOverlap(griever, avatar) || distance <= GRIEVER_CONTACT_PAD) {
      handleGrieverContact(griever);
    }
  });
}

createjs.Ticker.addEventListener("tick", updateGrievers);

// ====================== FLICKERING ======================
function startFlickeringCurrentCheckpoint() {
  stopAllFlickering();
  const cp = checkpoints[currentCheckpointIndex];
  if (!cp || !cp.clip) return;
  createjs.Tween.get(cp.clip, { loop: true })
    .to({ alpha: 0.4, scaleX: 0.92, scaleY: 0.92 }, 400)
    .to({ alpha: 1,   scaleX: 1,    scaleY: 1    }, 400);
}

function stopAllFlickering() {
  checkpoints.forEach(cp => {
    if (cp.clip) {
      createjs.Tween.removeTweens(cp.clip);
      cp.clip.scaleX = 1; cp.clip.scaleY = 1;
    }
  });
  refreshCheckpointLabels();
}

// ====================== BUTTON FEEDBACK ======================
function addStrongFeedback(btn) {
  if (!btn) return;
  const ox = btn.scaleX, oy = btn.scaleY;
  btn.addEventListener("mousedown", () => { btn.scaleX = ox * 0.75; btn.scaleY = oy * 0.75; btn.alpha = 0.7; });
  btn.addEventListener("pressup",   () => { btn.scaleX = ox; btn.scaleY = oy; btn.alpha = 1; });
}

addStrongFeedback(this.btnUp);
addStrongFeedback(this.btnDown);
addStrongFeedback(this.btnLeft);
addStrongFeedback(this.btnRight);

// ====================== MOVEMENT ======================
function moveAvatarStep(dx, dy) {
  if (!avatar || (gameState !== "PLAYING" && gameState !== "QUESTION")) return false;

  const targetX = avatar.x + dx;
  const targetY = avatar.y + dy;
  let moved = false;

  if (dx !== 0) {
    if (!isCollidingWithAnyWall(targetX, avatar.y)) {
      avatar.x = targetX;
      moved = true;
    } else {
      stopMoving();
      return false;
    }
  }

  if (dy !== 0) {
    if (!isCollidingWithAnyWall(avatar.x, targetY)) {
      avatar.y = targetY;
      moved = true;
    } else {
      stopMoving();
      return false;
    }
  }

  checkAnswerCollision();
  checkExitCollision();
  return moved;
}

function startMoving(dx, dy) {
  if (gameState !== "PLAYING" && gameState !== "QUESTION") return;
  if (moveInterval) clearInterval(moveInterval);
  moveInterval = setInterval(() => {
    if (gameState !== "PLAYING" && gameState !== "QUESTION") return;
    moveAvatarStep(dx, dy);
  }, 50);
  moveAvatarStep(dx, dy);
}

function stopMoving() {
  if (moveInterval) clearInterval(moveInterval);
  moveInterval = null;
}

function bindMoveButton(btn, dx, dy) {
  if (!btn) return;
  btn.addEventListener("mousedown", () => startMoving(dx, dy));
  btn.addEventListener("click", () => startMoving(dx, dy));
}

bindMoveButton(this.btnRight,  moveSpeed, 0);
bindMoveButton(this.btnLeft,  -moveSpeed, 0);
bindMoveButton(this.btnUp,    0, -moveSpeed);
bindMoveButton(this.btnDown,  0,  moveSpeed);

// ====================== CHECKPOINT COLLISION ======================
function checkCheckpointCollision() {
  if (gameState !== "PLAYING" || checkpointCooldown) return;
  const cp = checkpoints[currentCheckpointIndex];
  if (!cp || !cp.clip || answered.has(cp.id)) return;
  if (objectsOverlap(avatar, cp.clip)) {
    if (lastTriggeredCP !== cp.id) { lastTriggeredCP = cp.id; showQuestion(cp.qIndex, cp.id); }
  } else {
    if (lastTriggeredCP === cp.id) lastTriggeredCP = null;
  }
}

function checkExitCollision() {
  if (answered.size >= questions.length && objectsOverlap(avatar, exitZone)) {
    gameState = "WIN";
    if (timerInterval) clearInterval(timerInterval);
    if (moveInterval)  clearInterval(moveInterval);
    triggerWin();
  }
}

// ====================== SHOW QUESTION ======================
function showQuestion(idx, cpID) {
  gameState = "QUESTION";
  questionLocked = false;
  stopMoving();
  answerCollisionArmed = false;
  // ---- FIX: clear all contact locks so wrong-answer re-entry always works ----
  optionContactLocks.clear();
  const q = questions[idx];
  questionPanel.visible = true;
  //if (questionPanel.qText) questionPanel.qText.text = q.q;
  if (questionPanel.qText) {
        const qText = questionPanel.qText;

        // ── Store original values on first run only ──────────────────────────
        // Ignore a first-frame scale under 1 so auto-start does not lock in
        // a tiny/soft transform and make the large question look blurry.
        if (qText._originY == null) {
            const liveSX = qText.scaleX != null ? qText.scaleX : 1;
            const liveSY = qText.scaleY != null ? qText.scaleY : 1;
            qText._originY  = qText.y;
            qText._originSX = liveSX >= 0.9 ? liveSX : 1;
            qText._originSY = liveSY >= 0.9 ? liveSY : 1;
            qText._originLineWidth = Number(qText.lineWidth) > 0 ? Number(qText.lineWidth) : 794;
        }

        const originY  = qText._originY;
        const originSX = qText._originSX;
        const originSY = qText._originSY;
        const originLineWidth = qText._originLineWidth;
        const smallSX  = originSX * 0.55;
        const smallSY  = originSY * 0.55;
        const compactLineWidth = 1400;

        // ── HARD RESET everything first ───────────────────────────────────────
        createjs.Tween.removeTweens(qText);
        if (qText.uncache) qText.uncache();
        qText.visible = true;
        qText.alpha   = 1;
        qText.y       = originY;
        qText.scaleX  = originSX;
        qText.scaleY  = originSY;
        qText.lineWidth = originLineWidth;
        qText.text    = q.q;
        if (qText.cache) {
            const twCache = qText.getMeasuredWidth  ? qText.getMeasuredWidth()  : 800;
            const thCache = qText.getMeasuredHeight ? qText.getMeasuredHeight() : 80;
            const align = qText.textAlign || "left";
            const baseX = align === "center" ? -twCache / 2 : align === "right" ? -twCache : 0;
            qText.cache(baseX - 12, -12, twCache + 24, thCache + 24, 2);
        }

        // ── Build / reuse background Shape ───────────────────────────────────
        if (!qText._bgShape) {
            const bg = new createjs.Shape();
            bg.name         = "qTextBg";
            bg.mouseEnabled = false;
            const parent = qText.parent || questionPanel;
            parent.addChildAt(bg, Math.max(0, parent.getChildIndex(qText)));
            qText._bgShape = bg;
        }

        const bg   = qText._bgShape;
        const padX = 30;
        const padY = 150;
        const tw   = qText.getMeasuredWidth  ? qText.getMeasuredWidth()  : 220;
        const th   = qText.getMeasuredHeight ? qText.getMeasuredHeight() : 28;
        const bgW  = tw + padX * 2;
        const bgH  = th + padY * 2;
        const bgX  = qText.x - bgW / 2;
        const bgY  = qText.y - padY;

        // ── Hard reset bg ─────────────────────────────────────────────────────
        createjs.Tween.removeTweens(bg);
        bg.x       = 0;
        bg.y       = 0;
        bg.alpha   = 1;
        bg.visible = true;

        bg.graphics
            .clear()
            .setStrokeStyle(1.5)
            .beginStroke("rgba(91, 98, 105, 0.8)")
            .beginFill("rgba(10,20,50,0.94)")
            .drawRoundRect(bgX, bgY, bgW, bgH, 10)
            .endFill()
            .endStroke();

        // ── Full sequence ─────────────────────────────────────────────────────
        createjs.Tween.get(qText)
            .wait(3000)
            // Step 3: drop and fade out
            .to({ y: originY + 350, alpha: 0 }, 500, createjs.Ease.sineIn)
            // Step 4: snap invisibly to lower position, small scale
            .call(() => {
            if (qText.uncache) qText.uncache();
            qText.y      = originY + 240;
            qText.scaleX = smallSX;
            qText.scaleY = smallSY;
            qText.lineWidth = compactLineWidth;
            qText.alpha  = 0;
            })
            // Step 5: rise up and fade in as small text
            .to({ y: originY + 300, alpha: 1 }, 480, createjs.Ease.sineOut);
            // Step 6: stays wider at the original vertical position

        // Background fades out with the drop, stays hidden during small text
        createjs.Tween.get(bg)
            .wait(3000)
            .to({ alpha: 0 }, 500, createjs.Ease.sineIn)
            .call(() => {
            bg.visible = false;
            bg.alpha   = 1;  // reset alpha ready for next question
            });
    }
  questionPanel.qIndex = idx;
  questionPanel.cpID   = cpID;
  setQuestionOptionTexts(q);
  enableAllOptions();
  resetAllOptionVisuals();
  hideAllLegacyAnswerVisuals();
  updateFeedbackDisplay(INITIAL_FEEDBACK_TEXT, null);
  updateLivesDisplay();
  playQuestionAudio(idx);
}

function findOptionLabelField(optionClip) {
  if (!optionClip) return null;
  const directNames = ["labelText", "txt", "text", "optionText", "answerText"];
  for (let i = 0; i < directNames.length; i++) {
    if (optionClip[directNames[i]]) return optionClip[directNames[i]];
  }

  return findFirstNonVisualTextDescendant(optionClip);
}

function bringDisplayObjectToFront(obj) {
  if (!obj || !obj.parent || !obj.parent.setChildIndex) return;
  obj.parent.setChildIndex(obj, obj.parent.numChildren - 1);
}

function bringDescendantBranchToFront(root, obj) {
  if (!root || !obj) return;

  let current = obj;
  while (current && current !== root) {
    bringDisplayObjectToFront(current);
    current = current.parent;
  }
}

function sendLikelyOptionBackgroundsBack(optionClip) {
  if (!optionClip?.children || !optionClip.setChildIndex) return;

  const likelyBackgrounds = optionClip.children.filter(child => {
    const name = String(child?.name || "").toLowerCase();
    return name.includes("bg") ||
      name.includes("background") ||
      name.includes("backing") ||
      name.includes("rect") ||
      name.includes("rectangle");
  });

  likelyBackgrounds.reverse().forEach(child => {
    optionClip.setChildIndex(child, 0);
  });
}

function normalizeOptionLayering(opt, optionClip, currentQuestionIndex) {
  if (!optionClip) return;

  sendLikelyOptionBackgroundsBack(optionClip);

  for (let i = 0; i <= questions.length; i++) {
    const visualClip = getVisualClip(opt, i);
    if (visualClip && (i === currentQuestionIndex || visualClip.visible !== false)) {
      bringDescendantBranchToFront(optionClip, visualClip);
    }
  }

  const labelField = findOptionLabelField(optionClip);
  bringDescendantBranchToFront(optionClip, labelField);
}

function normalizeAllOptionLayering(currentQuestionIndex) {
  OPTION_NAMES.forEach(opt => normalizeOptionLayering(opt, questionPanel?.[opt], currentQuestionIndex));
}

function isVisualContainer(container) {
  const name = String(container?.name || "").toLowerCase();
  return name.indexOf("_visual") !== -1 || name.indexOf("visual") !== -1;
}

function findFirstNonVisualTextDescendant(container) {
  if (!container || !container.children) return null;

  for (let i = 0; i < container.children.length; i++) {
    const child = container.children[i];
    if (!child) continue;
    if (typeof child.text === "string") return child;
  }

  for (let i = 0; i < container.children.length; i++) {
    const child = container.children[i];
    if (!child || isVisualContainer(child)) continue;

    const nested = findFirstNonVisualTextDescendant(child);
    if (nested) return nested;
  }

  return null;
}

function ensureAnswerBallLabel(ball) {
  if (!ball || !ball.addChild) return null;
  if (ball._oxidationNumberLabel) return ball._oxidationNumberLabel;

  const label = new createjs.Text("", "bold 26px Arial", "#ffd08a");
  label.name = "oxidationNumberLabel";
  label.textAlign = "center";
  label.textBaseline = "middle";
  label.mouseEnabled = false;
  label.shadow = new createjs.Shadow("rgba(0,0,0,0.9)", 0, 2, 5);

  const bounds = ball.getBounds ? ball.getBounds() : null;
  label.x = bounds ? bounds.x + bounds.width / 2 : 0;
  label.y = bounds ? bounds.y + bounds.height / 2 : 0;
  ball.addChild(label);
  ball._oxidationNumberLabel = label;
  return label;
}

function clearAnswerBallLabels() {
  BALL_NAMES.forEach(ballName => {
    const ball = getKnockBallByName(ballName);
    if (ball?._oxidationNumberLabel) ball._oxidationNumberLabel.text = "";
  });
}

function setQuestionOptionTexts(question) {
  clearAnswerBallLabels();
  const opts = ["optA","optB","optC","optD"];
  opts.forEach((opt, index) => {
    // The Answer A-D clips may not be placed inside questionPanel.
    // Do not stop here, because the visible answer targets are the
    // stage-level ballA, ballB, ballC and ballD clips.
    const optionClip = questionPanel?.[opt] || null;
    if (optionClip) {
      optionClip.visible = true;
      const labelField = findOptionLabelField(optionClip);
      if (labelField) labelField.text = question.o[index] || "";
    }

    const ball = getAnswerBall(index);
    if (ball) ball.visible = true;
    const ballLabel = ensureAnswerBallLabel(ball);
    if (ballLabel) {
      ballLabel.text = question.o[index] || "";
      ballLabel.visible = true;
      bringDisplayObjectToFront(ballLabel);
    }
  });
  normalizeAllOptionLayering(questionPanel?.qIndex || 0);
}

// ====================== VISUAL RESET ======================
function resetAllOptionVisuals() {
  const opts = ["optA","optB","optC","optD"];

  opts.forEach(opt => {
    const clip = getVisualClip(opt, 0);
    if (clip) {
      clip.visible = false;
      createjs.Tween.removeTweens(clip);
      clip.scaleX = 1; clip.scaleY = 1; clip.alpha = 1;
    }
  });

  for (let n = 2; n <= 10; n++) {
    opts.forEach(opt => {
      const clip = questionPanel[opt]?.[opt + "_visual" + n];
      if (clip) {
        clip.visible = false;
        createjs.Tween.removeTweens(clip);
        clip.scaleX = 1; clip.scaleY = 1; clip.alpha = 1;
      }
    });
  }
}

function hideAllLegacyAnswerVisuals() {
  const descendants = [];
  collectNamedDescendants(questionPanel, descendants, new Set());
  descendants.forEach(child => {
    const name = String(child?.name || "").toLowerCase();
    if (name.includes("visual")) {
      child.visible = false;
      createjs.Tween.removeTweens(child);
    }
  });
}

// ====================== VISUAL ROUTING ======================
function showVisualsForQuestion(idx) {
  const opts = ["optA","optB","optC","optD"];
  if (idx === 0) {
    opts.forEach(opt => {
      const clip = getVisualClip(opt, 0);
      if (clip) clip.visible = true;
    });
  } else {
    const suffix = "visual" + (idx + 1);
    opts.forEach(opt => {
      const clip = questionPanel[opt]?.[opt + "_" + suffix];
      if (clip) clip.visible = true;
    });
  }
  normalizeAllOptionLayering(idx);
  startVisualAnimations(idx);
}

function enableAllOptions() {
  optionContactLocks.clear();
  OPTION_NAMES.forEach(opt => {
    if (questionPanel[opt]) {
      questionPanel[opt].mouseEnabled = false;
      questionPanel[opt].alpha        = 1;
      restoreOptionStanding(questionPanel[opt]);
    }
  });
  BALL_NAMES.forEach(ballName => {
    restoreDisplayObjectStanding(getKnockBallByName(ballName));
  });
}

function disableAllOptions() {
  OPTION_NAMES.forEach(opt => {
    if (questionPanel[opt]) {
      questionPanel[opt].mouseEnabled = false;
    }
  });
}

function ensureFeedbackBg() {
  if (!questionPanel?.fbText) return;
  const fbParent = questionPanel.fbText.parent || questionPanel;
  if (feedbackBgShape && feedbackBgParent === fbParent) return;

  feedbackBgShape = new createjs.Shape();
  feedbackBgParent = fbParent;
  feedbackBgShape.visible = false;
  feedbackBgParent.addChildAt(feedbackBgShape, Math.max(0, feedbackBgParent.getChildIndex(questionPanel.fbText)));
}

function updateFeedbackDisplay(text, color) {
  if (!questionPanel?.fbText) return;
  ensureFeedbackBg();

  const fb = questionPanel.fbText;
  fb.text = text || "";
  fb.color = color || "#f8fafc";

  if (!text) {
    if (feedbackBgShape) feedbackBgShape.visible = false;
    return;
  }

  const padX = 14;
  const padY = 10;
  const bounds = fb.getBounds ? fb.getBounds() : null;
  const measuredWidth = bounds ? bounds.width : fb.getMeasuredWidth();
  const measuredHeight = bounds
    ? bounds.height
    : (fb.getMeasuredLineHeight ? fb.getMeasuredLineHeight() : 22) * Math.max(1, String(text).split("\n").length);
  const width = Math.max(140, measuredWidth + padX * 2);
  const height = Math.max(34, measuredHeight + padY * 2);

  let bgColor = "rgba(15,23,42,0.82)";
  let strokeColor = "rgba(255,255,255,0.88)";
  if (color === "#134937") {
    fb.color = "#8fffd1";
    bgColor = "rgba(6,78,59,0.88)";
    strokeColor = "rgba(110,255,208,0.95)";
  } else if (color === "#741313") {
    fb.color = "#ffd0d0";
    bgColor = "rgba(127,29,29,0.9)";
    strokeColor = "rgba(255,170,170,0.96)";
  }

  const textX = bounds ? fb.x + bounds.x : fb.x;
  const textY = bounds ? fb.y + bounds.y : fb.y;
  const bgX = textX - padX;
  const bgY = textY - padY;

  if (feedbackBgShape) {
    feedbackBgShape.visible = true;
    feedbackBgShape.graphics
      .clear()
      .setStrokeStyle(1)
      .beginStroke(strokeColor)
      .beginFill(bgColor)
      .drawRoundRect(bgX, bgY, width, height, 10)
      .endFill()
      .endStroke();
  }
}

// ====================== VISUAL ANIMATIONS PER QUESTION ======================
function vis(opt, idx) {
  return getVisualClip(opt, idx);
}

function getVisualClip(opt, idx) {
  const optionClip = questionPanel?.[opt];
  if (!optionClip) return null;

  if (idx === 0) {
    return optionClip[opt + "_visual"] || optionClip[opt + "_visual0"] || null;
  }

  return optionClip[opt + "_visual" + (idx + 1)] || null;
}

function startVisualAnimations(idx) {
  switch (idx) {
    case 0:
      animateRandomMovement(vis("optA", 0));
      animateRandomMovement(vis("optB", 0));
      pulseFade(vis("optC", 0), 180);
      pulseFade(vis("optD", 0), 150);
      break;
    case 1:
      animateRandomMovement(vis("optC", 1));
      animateRandomMovement(vis("optD", 1), 3);
      break;
  }
}

// ====================== ANIMATION HELPERS ======================
function pulseFade(obj, speed) {
  if (!obj) return;
  createjs.Tween.get(obj, { loop: true })
    .to({ alpha: 0.35 }, speed).to({ alpha: 1 }, speed);
}

function pulseScale(obj, maxScale, speed) {
  if (!obj) return;
  createjs.Tween.get(obj, { loop: true })
    .to({ scaleX: maxScale, scaleY: maxScale, alpha: 0.85 }, speed, createjs.Ease.sineInOut)
    .to({ scaleX: 1,        scaleY: 1,        alpha: 1    }, speed, createjs.Ease.sineInOut);
}

function nudgeX(obj, amount, speed) {
  if (!obj) return;
  const ox = obj.x;
  createjs.Tween.get(obj, { loop: true })
    .to({ x: ox + amount }, speed, createjs.Ease.sineInOut)
    .to({ x: ox - amount }, speed, createjs.Ease.sineInOut)
    .to({ x: ox          }, speed, createjs.Ease.sineInOut);
}

function animateRandomMovement(container, speed = 2) {
  if (!container?.children) return;
  container.children.forEach(child => {
    if (!child) return;
    child.vx = Math.random() * speed * 2 - speed;
    child.vy = Math.random() * speed * 2 - speed;
    const interval = setInterval(() => {
      if (gameState !== "QUESTION") { clearInterval(interval); return; }
      child.x += child.vx; child.y += child.vy;
      if (child.x < -30 || child.x > 30) child.vx *= -0.8;
      if (child.y < -30 || child.y > 30) child.vy *= -0.8;
    }, 60);
  });
}

function stopQuestionAudio() {
  if (!currentQuestionSound) return;

  if (currentQuestionSound.stop) {
    currentQuestionSound.stop();
  } else if (currentQuestionSound.pause) {
    currentQuestionSound.pause();
    currentQuestionSound.currentTime = 0;
  } else if (currentQuestionSound.htmlElement?.pause) {
    currentQuestionSound.htmlElement.pause();
    currentQuestionSound.htmlElement.currentTime = 0;
  }

  currentQuestionSound = null;
}

function playQuestionAudio(idx) {
  stopQuestionAudio();

  const id = questions[idx]?.audioId || "Q" + (idx + 1);
  const ids = [id, id.toLowerCase(), "question" + (idx + 1), "Question" + (idx + 1)];

  if (createjs?.Sound?.play) {
    for (let i = 0; i < ids.length; i++) {
      const instance = createjs.Sound.play(ids[i]);
      if (instance && instance.playState !== createjs.Sound.PLAY_FAILED) {
        currentQuestionSound = instance;
        return true;
      }
    }
  }

  const clip = getFirstAvailableClip(ids);
  if (clip) {
    if (clip.htmlElement?.play) {
      clip.htmlElement.currentTime = 0;
      clip.htmlElement.play().catch(() => {});
      currentQuestionSound = clip;
      return true;
    }

    if (clip.gotoAndPlay) {
      clip.gotoAndPlay(0);
      currentQuestionSound = clip;
      return true;
    }
  }

  const extensions = ["mp3", "wav", "ogg", "m4a"];
  const folders = ["", "audio/", "audios/", "sounds/"];
  const candidates = [];
  folders.forEach(folder => {
    extensions.forEach(ext => candidates.push(folder + id + "." + ext));
  });

  return playQuestionAudioFileCandidates(candidates, 0);
}

function playQuestionAudioFileCandidates(candidates, index) {
  if (index >= candidates.length) return false;

  const audio = new Audio(candidates[index]);
  currentQuestionSound = audio;
  audio.onerror = () => {
    if (currentQuestionSound === audio) {
      currentQuestionSound = null;
      playQuestionAudioFileCandidates(candidates, index + 1);
    }
  };
  audio.currentTime = 0;
  audio.play().catch(() => {
    if (currentQuestionSound === audio) {
      currentQuestionSound = null;
      playQuestionAudioFileCandidates(candidates, index + 1);
    }
  });
  return true;
}

function playFeedbackSound(kind) {
  const soundIds = kind === "correct"
    ? ["ding", "correctDing", "correct", "success", "rightanswer", "correctanswer"]
    : ["buzz", "wrongBuzz", "incorrect", "wrong", "fail", "wronganswer", "incorrectanswer"];

  if (createjs?.Sound?.play) {
    for (let i = 0; i < soundIds.length; i++) {
      const instance = createjs.Sound.play(soundIds[i]);
      if (instance && instance.playState !== createjs.Sound.PLAY_FAILED) {
        return true;
      }
    }
  }

  const clipNames = kind === "correct"
    ? ["ding", "dingSound", "correctDing", "correctSound", "successSound"]
    : ["buzz", "buzzSound", "wrongBuzz", "incorrectSound", "failSound"];

  const clip = getFirstAvailableClip(clipNames);
  if (!clip) return playSynthFeedbackSound(kind);

  if (clip.htmlElement?.play) {
    clip.htmlElement.currentTime = 0;
    clip.htmlElement.play().catch(() => {});
    return true;
  }

  if (clip.gotoAndPlay) {
    clip.gotoAndPlay(0);
    return true;
  }

  return playSynthFeedbackSound(kind);
}

function playSynthFeedbackSound(kind) {
  const AudioCtx = window.AudioContext || window.webkitAudioContext;
  if (!AudioCtx) return false;

  if (!playSynthFeedbackSound.ctx) {
    playSynthFeedbackSound.ctx = new AudioCtx();
  }

  const ctx = playSynthFeedbackSound.ctx;
  if (ctx.state === "suspended") {
    ctx.resume().catch(() => {});
  }

  const now = ctx.currentTime;
  const notes = kind === "correct"
    ? [
        { freq: 880, start: 0, end: 0.12, gain: 0.12 },
        { freq: 1174, start: 0.12, end: 0.32, gain: 0.1 }
      ]
    : [
        { freq: 220, start: 0, end: 0.12, gain: 0.12 },
        { freq: 165, start: 0.12, end: 0.3, gain: 0.1 }
      ];

  notes.forEach(note => {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = kind === "correct" ? "sine" : "sawtooth";
    osc.frequency.setValueAtTime(note.freq, now + note.start);
    gain.gain.setValueAtTime(0.0001, now + note.start);
    gain.gain.exponentialRampToValueAtTime(note.gain, now + note.start + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + note.end);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now + note.start);
    osc.stop(now + note.end);
  });

  return true;
}

function snapTogether(container) {
  if (!container?.children || container.children.length < 2) {
    if (container) pulseFade(container, 400); return;
  }
  const a = container.children[0], b = container.children[1];
  if (!a || !b) return;
  const ax = a.x, bx = b.x;
  createjs.Tween.get(a, { loop: true })
    .to({ x: ax + 12 }, 600, createjs.Ease.sineInOut)
    .to({ x: ax      }, 600, createjs.Ease.bounceOut).wait(400);
  createjs.Tween.get(b, { loop: true })
    .to({ x: bx - 12 }, 600, createjs.Ease.sineInOut)
    .to({ x: bx      }, 600, createjs.Ease.bounceOut).wait(400);
}

function explosionShake(obj) {
  if (!obj) return;
  const ox = obj.x, oy = obj.y;
  createjs.Tween.get(obj, { loop: true })
    .to({ x: ox+5, y: oy-5 }, 60).to({ x: ox-5, y: oy+5 }, 60)
    .to({ x: ox+4, y: oy+4 }, 60).to({ x: ox-4, y: oy-4 }, 60)
    .to({ x: ox,   y: oy   }, 60).wait(500);
}

function electricFlicker(obj, speed) {
  if (!obj) return;
  createjs.Tween.get(obj, { loop: true })
    .to({ alpha: 0.2 }, speed)
    .to({ alpha: 1   }, speed / 2)
    .to({ alpha: 0.6 }, speed / 2)
    .to({ alpha: 1   }, speed);
}

function bounceIn(obj) {
  if (!obj) return;
  const oy = obj.y; obj.y = oy + 20; obj.alpha = 0;
  createjs.Tween.get(obj)
    .to({ y: oy, alpha: 1 }, 500, createjs.Ease.bounceOut)
    .call(() => {
      createjs.Tween.get(obj, { loop: true })
        .to({ y: oy - 4 }, 600, createjs.Ease.sineInOut)
        .to({ y: oy     }, 600, createjs.Ease.sineInOut);
    });
}

function featherFloat(obj) {
  if (!obj) return;
  const oy = obj.y;
  createjs.Tween.get(obj, { loop: true })
    .to({ y: oy - 10, alpha: 0.9 }, 1200, createjs.Ease.sineInOut)
    .to({ y: oy,      alpha: 1   }, 1200, createjs.Ease.sineInOut);
}

function weightDrop(obj) {
  if (!obj) return;
  const oy = obj.y;
  createjs.Tween.get(obj, { loop: true })
    .to({ y: oy + 8 }, 200, createjs.Ease.bounceOut)
    .to({ y: oy     }, 600, createjs.Ease.sineOut).wait(300);
}

// ====================== CORRECT-ANSWER SPECIAL EFFECTS ======================
function highlightCorrectQ4() {
  const a = questionPanel.optA?.optA_visual4;
  if (!a) return;
  createjs.Tween.removeTweens(a);
  createjs.Tween.get(a)
    .to({ scaleX:1.18,scaleY:1.18,alpha:1   },180)
    .to({ scaleX:1,   scaleY:1,   alpha:0.7 },180)
    .to({ scaleX:1.18,scaleY:1.18,alpha:1   },180)
    .to({ scaleX:1,   scaleY:1,   alpha:0.7 },180)
    .to({ scaleX:1.18,scaleY:1.18,alpha:1   },180)
    .to({ scaleX:1,   scaleY:1,   alpha:1   },300);
}

function bondSparkCorrect() {
  const a = questionPanel.optA?.optA_visual5;
  if (!a) return;
  createjs.Tween.removeTweens(a);
  createjs.Tween.get(a)
    .to({ scaleX:1.2, scaleY:1.2, alpha:1   },150)
    .to({ scaleX:0.95,scaleY:0.95,alpha:0.8 },100)
    .to({ scaleX:1.15,scaleY:1.15,alpha:1   },150)
    .to({ scaleX:1,   scaleY:1,   alpha:1   },200);
}

function electricSparkCorrect() {
  const a = questionPanel.optA?.optA_visual6;
  if (!a) return;
  createjs.Tween.removeTweens(a);
  createjs.Tween.get(a)
    .to({alpha:0.1},80).to({alpha:1},80)
    .to({alpha:0.1},80).to({alpha:1},80)
    .to({alpha:0.1},80).to({alpha:1},120);
}

function electricBuzzCorrect() {
  const a = questionPanel.optA?.optA_visual8;
  if (!a) return;
  createjs.Tween.removeTweens(a);
  const ox = a.x;
  createjs.Tween.get(a)
    .to({x:ox+3},50).to({x:ox-3},50)
    .to({x:ox+3},50).to({x:ox-3},50)
    .to({x:ox  },50);
}

function featherFloatCorrect() {
  const a = questionPanel.optA?.optA_visual9;
  if (!a) return;
  createjs.Tween.removeTweens(a);
  const oy = a.y;
  createjs.Tween.get(a)
    .to({ y: oy-20, alpha:0.7 },600,createjs.Ease.sineOut)
    .to({ y: oy,    alpha:1   },600,createjs.Ease.sineIn);
}

function confettiBurst() {
  ["optA","optB","optC","optD"].forEach((opt, i) => {
    const v = questionPanel[opt]?.[opt + "_visual10"];
    if (!v) return;
    createjs.Tween.removeTweens(v);
    const angle = (i / 4) * Math.PI * 2;
    createjs.Tween.get(v)
      .to({ x:v.x+Math.cos(angle)*30, y:v.y+Math.sin(angle)*30,
            alpha:0, scaleX:1.5, scaleY:1.5 }, 800, createjs.Ease.sineOut);
  });
}

// ====================== FIXED: ANSWER BALL LOOKUP ======================

// Maps option index (0–3) to ball name for the current question.
// Correct answer index → the randomly assigned correct ball for this run.
// Wrong answer indices → remaining BALL_NAMES in order, skipping the correct ball.
function getBallNameForAnswerIndex(index) {
  const qIndex = questionPanel?.qIndex ?? 0;
  const question = questions[qIndex];
  if (!question) return BALL_NAMES[index];

  const correctBall = correctBallByQuestion[qIndex] || BALL_NAMES[question.c];

  if (index === question.c) return correctBall;

  // Distribute remaining balls across wrong-answer slots in BALL_NAMES order
  const wrongBalls   = BALL_NAMES.filter(b => b !== correctBall);
  const wrongIndexes = [0, 1, 2, 3].filter(i => i !== question.c);
  const pos          = wrongIndexes.indexOf(index);
  return wrongBalls[pos] ?? BALL_NAMES[index];
}

// Finds the ball clip for an answer option.
// Search: direct child of option → named descendant of option →
//         direct child of questionPanel → named descendant of questionPanel →
//         direct child of stageRoot → named descendant of stageRoot
function getAnswerBall(index) {
  const ballName   = getBallNameForAnswerIndex(index);
  const optionClip = getAnswerOption(index);

  if (optionClip?.[ballName])                              return optionClip[ballName];
  const fromOption = getNamedDescendantByExactName(optionClip, ballName);
  if (fromOption)                                          return fromOption;
  if (questionPanel?.[ballName])                           return questionPanel[ballName];
  const fromPanel = getNamedDescendantByExactName(questionPanel, ballName);
  if (fromPanel)                                           return fromPanel;
  if (stageRoot?.[ballName])                               return stageRoot[ballName];
  return getNamedDescendantByExactName(stageRoot, ballName) ?? null;
}

function getKnockBallByName(ballName) {
  return questionPanel?.[ballName] ||
    getNamedDescendantByExactName(questionPanel, ballName) ||
    stageRoot?.[ballName] ||
    getNamedDescendantByExactName(stageRoot, ballName) ||
    null;
}

// Hit target for collision: prefer the ball, fall back to the whole option clip.
function getAnswerHitTarget(index) {
  return getAnswerBall(index) ?? getAnswerOption(index);
}

// ====================== ANSWER HANDLING ======================
function getAnswerOption(index) {
  return questionPanel?.[OPTION_NAMES[index]] || null;
}

function getNamedDescendantByExactName(container, targetName) {
  if (!container) return null;
  if (String(container.name || "").toLowerCase() === targetName.toLowerCase()) return container;

  const namedChildren = [];
  collectNamedDescendants(container, namedChildren, new Set());
  return namedChildren.find(child => String(child?.name || "").toLowerCase() === targetName.toLowerCase()) || null;
}

function getNamedDescendantsByExactName(container, targetName) {
  if (!container) return [];

  const target = targetName.toLowerCase();
  const matches = [];
  if (String(container.name || "").toLowerCase() === target) matches.push(container);

  const namedChildren = [];
  collectNamedDescendants(container, namedChildren, new Set());
  namedChildren.forEach(child => {
    if (String(child?.name || "").toLowerCase() === target) matches.push(child);
  });

  return matches;
}

function isDisplayObjectEffectivelyVisible(obj) {
  let current = obj;
  while (current) {
    if (current.visible === false) return false;
    current = current.parent;
  }
  return true;
}

function getDisplayObjectCenterPoint(obj) {
  if (!obj) return null;

  const rect = getGlobalDisplayRect(obj);
  if (rect) {
    return {
      x: rect.x + rect.width / 2,
      y: rect.y + rect.height / 2,
      radius: Math.max(24, Math.min(52, Math.max(rect.width, rect.height) * 0.65))
    };
  }

  const point = obj.localToGlobal ? obj.localToGlobal(0, 0) : { x: obj.x, y: obj.y };
  return point ? { x: point.x, y: point.y, radius: 52 } : null;
}

function getDisplayObjectHitRect(obj, fallbackSize = 52) {
  if (!obj) return null;

  const rect = getGlobalDisplayRect(obj);
  if (rect) return rect;

  const point = obj.localToGlobal ? obj.localToGlobal(0, 0) : { x: obj.x, y: obj.y };
  if (!point) return null;

  const half = fallbackSize / 2;
  return {
    x: point.x - half,
    y: point.y - half,
    width: fallbackSize,
    height: fallbackSize
  };
}

function cacheOptionStartTransform(optionClip) {
  if (!optionClip || optionStartTransforms.has(optionClip)) return;
  optionStartTransforms.set(optionClip, {
    x: optionClip.x,
    y: optionClip.y,
    rotation: optionClip.rotation || 0,
    scaleX: optionClip.scaleX == null ? 1 : optionClip.scaleX,
    scaleY: optionClip.scaleY == null ? 1 : optionClip.scaleY,
    alpha: optionClip.alpha == null ? 1 : optionClip.alpha
  });
}

function restoreOptionStanding(optionClip) {
  restoreDisplayObjectStanding(optionClip);
}

function restoreDisplayObjectStanding(optionClip) {
  if (!optionClip) return;
  cacheOptionStartTransform(optionClip);
  const start = optionStartTransforms.get(optionClip);
  createjs.Tween.removeTweens(optionClip);
  optionClip.x = start.x;
  optionClip.y = start.y;
  optionClip.rotation = start.rotation;
  optionClip.scaleX = start.scaleX;
  optionClip.scaleY = start.scaleY;
  optionClip.alpha = start.alpha;
}

function knockOptionOver(optionClip) {
  if (!optionClip) return;
  cacheOptionStartTransform(optionClip);
  const start = optionStartTransforms.get(optionClip);
  createjs.Tween.removeTweens(optionClip);
  createjs.Tween.get(optionClip)
    .to({ rotation: start.rotation + 16, x: start.x + 8, y: start.y - 6, scaleY: start.scaleY * 0.96 }, 90, createjs.Ease.sineOut)
    .to({ rotation: start.rotation + 88, x: start.x + 34, y: start.y + 30, scaleY: start.scaleY * 0.7, alpha: 0.68 }, 300, createjs.Ease.bounceOut);
}

function bumpOptionWithoutRotating(optionClip) {
  if (!optionClip) return;
  cacheOptionStartTransform(optionClip);
  const start = optionStartTransforms.get(optionClip);
  createjs.Tween.removeTweens(optionClip);
  createjs.Tween.get(optionClip)
    .to({ x: start.x + 7, y: start.y - 4, scaleX: start.scaleX * 1.04, scaleY: start.scaleY * 1.04, alpha: 0.82 }, 90, createjs.Ease.sineOut)
    .to({ x: start.x, y: start.y, scaleX: start.scaleX, scaleY: start.scaleY, alpha: start.alpha }, 260, createjs.Ease.bounceOut);
}

function knockAnswerTarget(chosen) {
  const ballClip = getAnswerBall(chosen);
  if (ballClip) {
    bumpOptionWithoutRotating(ballClip);
    return ballClip;
  }

  const optionClip = getAnswerOption(chosen);
  bumpOptionWithoutRotating(optionClip);
  return optionClip;
}

function getHitRectForOption(index) {
  // Try to get the specific ball clip for this option/question
  const ball = getAnswerBall(index);
  if (ball && isDisplayObjectEffectivelyVisible(ball)) {
    const r = getGlobalDisplayRect(ball);
    if (r && r.width > 0 && r.height > 0) return r;
    // ball found but getBounds not ready — fall through to option clip
  }
  // Fall back to the option clip itself
  const opt = getAnswerOption(index);
  if (!opt || !isDisplayObjectEffectivelyVisible(opt)) return null;
  const r = getGlobalDisplayRect(opt);
  if (r && r.width > 0) return r;
  return getRect(opt);
}

function optionOverlapsAvatar(optionClip, index) {
  if (!avatar) return false;
  const hitTarget = getAnswerHitTarget(index);
  if (!hitTarget || !isDisplayObjectEffectivelyVisible(hitTarget)) return false;
  const avatarRect = getAvatarGlobalRectAt(avatar.x, avatar.y);
  if (!avatarRect) return false;
  const hitRect = getHitRectForOption(index);
  if (!hitRect) return false;
  // Expand the real answer target so click-step movement cannot skip past a small ball.
  const expanded = expandRect(hitRect, 10);
  return rectsOverlap(avatarRect, expanded);
}

function getAnswerCollisionDebugState() {
  const avatarRect = getAvatarGlobalRectAt(avatar?.x || 0, avatar?.y || 0);
  const avatarCenter = avatarRect ? {
    x: avatarRect.x + avatarRect.width / 2,
    y: avatarRect.y + avatarRect.height / 2
  } : null;
  return {
    gameState,
    questionVisible: !!questionPanel?.visible,
    questionLocked,
    armed: answerCollisionArmed,
    avatar: {
      x: avatar ? avatar.x : null,
      y: avatar ? avatar.y : null,
      rect: avatarRect,
      center: avatarCenter
    },
    options: OPTION_NAMES.map((opt, index) => {
      const clip = getAnswerOption(index);
      const hitTarget = getAnswerHitTarget(index);
      const hitPoint = getDisplayObjectCenterPoint(hitTarget);
      const distance = avatarCenter && hitPoint
        ? Math.round(Math.sqrt(Math.pow(avatarCenter.x - hitPoint.x, 2) + Math.pow(avatarCenter.y - hitPoint.y, 2)))
        : null;
      return {
        index,
        opt,
        ball: getBallNameForAnswerIndex(index),
        exists: !!clip,
        hitTarget: hitTarget ? (hitTarget.name || getBallNameForAnswerIndex(index) || opt) : null,
        visible: clip ? clip.visible : null,
        hitTargetVisible: hitTarget ? isDisplayObjectEffectivelyVisible(hitTarget) : null,
        locked: optionContactLocks.has(index),
        x: clip ? clip.x : null,
        y: clip ? clip.y : null,
        hitPoint,
        hitRect: getDisplayObjectHitRect(hitTarget),
        centerDistance: distance,
        radiusOverlaps: distance != null && hitPoint && distance <= hitPoint.radius
      };
    })
  };
}

function getGrieverCenterAt(griever, nx, ny) {
  const rect = getGrieverRectAt(griever, nx, ny);
  if (!rect) return { x: nx, y: ny };
  return {
    x: rect.x + rect.width / 2,
    y: rect.y + rect.height / 2
  };
}

function clampPointToPath(point, path) {
  if (!point || !path) return point;
  const rect = path.rect;
  return {
    x: Math.max(rect.x, Math.min(rect.x + rect.width, point.x)),
    y: Math.max(rect.y, Math.min(rect.y + rect.height, point.y))
  };
}

function getNearestPathToPoint(point) {
  if (!grieverPaths.length || !point) return null;

  let bestPath = null;
  let bestDistance = Infinity;
  grieverPaths.forEach(path => {
    const clamped = clampPointToPath(point, path);
    const dx = point.x - clamped.x;
    const dy = point.y - clamped.y;
    const distance = dx * dx + dy * dy;
    if (distance < bestDistance) {
      bestDistance = distance;
      bestPath = path;
    }
  });

  return bestPath;
}

function getPathNeighbors(path) {
  if (!path) return [];
  const expanded = expandRect(path.rect, GRIEVER_PATH_JOIN_PAD);
  return grieverPaths.filter(other => {
    if (other === path || !rectsOverlap(expanded, other.rect)) return false;
    return getRectDistanceSq(path.rect, other.rect) <= GRIEVER_PATH_JOIN_PAD * GRIEVER_PATH_JOIN_PAD;
  });
}

function getPathDirectionTowardPoint(path, point) {
  if (!path || !point) return Math.random() < 0.5 ? -1 : 1;
  const rect = path.rect;
  const midpoint = path.axis === "x"
    ? rect.x + rect.width / 2
    : rect.y + rect.height / 2;
  const value = path.axis === "x" ? point.x : point.y;
  return value < midpoint ? -1 : 1;
}

function createGrieverPathState(griever) {
  const center = getObjectCenter(griever);
  const currentPath = grieverPaths.find(path => pointInRect(center, path.rect, GRIEVER_PATH_JOIN_PAD)) ||
    getNearestPathToPoint(center);

  if (!currentPath) return null;

  return {
    path: currentPath,
    direction: Math.random() < 0.5 ? -1 : 1,
    pauseTicks: 0,
    stuckTicks: 0,
    oscillationTurns: 0,
    samePathReversals: 0,
    forceDiversion: false,
    collisionRetreatTicks: 0,
    forcedReturnPath: null,
    lastPath: null,
    lastX: griever.x,
    lastY: griever.y,
    previousPath: null,
    recentPaths: [currentPath]
  };
}

function refreshAnswerContactLocks() {
  OPTION_NAMES.forEach((opt, index) => {
    const optionClip = getAnswerOption(index);
    if (!optionOverlapsAvatar(optionClip, index)) {
      optionContactLocks.delete(index);
    }
  });
}

function checkAnswerCollision() {
  if (gameState !== "QUESTION" || questionLocked || !questionPanel?.visible) {
    return;
  }
  refreshAnswerContactLocks();

  const touchingAnyOption = OPTION_NAMES.some((opt, index) => optionOverlapsAvatar(getAnswerOption(index), index));
  if (!answerCollisionArmed) {
    if (!touchingAnyOption) {
      answerCollisionArmed = true;
    } else {
      return;
    }
  }

  for (let i = 0; i < OPTION_NAMES.length; i++) {
    if (optionContactLocks.has(i)) continue;
    const optionClip = getAnswerOption(i);
    if (!optionOverlapsAvatar(optionClip, i)) continue;
    optionContactLocks.add(i);
    handleAnswer(i);
    return;
  }
}

// ====================== FIX: handleAnswer ======================
// Two bugs fixed:
// 1. Correct path: was adding qIndex (number) to `answered` but checkpoint
//    checks answered.has(cp.id) (string like "cp1"). Fixed to add cp.id.
// 2. Wrong path: after feedback clears, answerCollisionArmed was not reset,
//    so the collision system never re-armed for the next attempt. Fixed to
//    reset answerCollisionArmed = false after the wrong-answer cooldown.

function handleAnswer(chosen) {
  if (gameState !== "QUESTION" || questionLocked) return;
  questionLocked = true;
  stopMoving();
  const q  = questions[questionPanel.qIndex];
  const currentCpId = questionPanel.cpID;
  const chosenOpt = getAnswerOption(chosen);
  const knockedTarget = knockAnswerTarget(chosen);
  beginAnswerFeedbackReset();

  if (chosen === q.c) {
    disableAllOptions();
    updateFeedbackDisplay("\u2713 " + q.ok, "#134937");
    playFeedbackSound("correct");

    // FIX 1: add the checkpoint id (string) so answered.has(cp.id) works correctly
    answered.add(currentCpId);
    score += 10;
    updateScoreDisplay();

    const nextQuestionIndex = questionPanel.qIndex + 1;
    const isLastQuestion = nextQuestionIndex >= questions.length;

    setTimeout(() => {
      questionPanel.visible = false;

      if (isLastQuestion) {
        endAnswerFeedbackReset(true, () => {
          if (timerInterval) clearInterval(timerInterval);
          if (moveInterval)  clearInterval(moveInterval);
          timerInterval = null;
          moveInterval  = null;
          triggerWin();
        });
        return;
      }

      // Advance checkpoint index and show next question
      currentCheckpointIndex = nextQuestionIndex;
      endAnswerFeedbackReset(true, () => {
        setTimeout(() => {
          showQuestion(nextQuestionIndex, checkpoints[nextQuestionIndex]?.id || "q" + (nextQuestionIndex + 1));
        }, 300);
      });
    }, ANSWER_FEEDBACK_MS);

  } else {
    loseLife("Wrong answer", true);
    updateFeedbackDisplay("\u2717 " + q.bad, "#741313");
    playFeedbackSound("wrong");
    if (lives <= 0) {
      setTimeout(() => {
        endAnswerFeedbackReset(true, () => {
          triggerFailed("3 wrong answers on one question");
        });
      }, ANSWER_FEEDBACK_MS);
    } else {
      const wrongTarget = knockedTarget || chosenOpt;
      if (wrongTarget) {
        wrongTarget.mouseEnabled = false;
        setTimeout(() => {
          if (wrongTarget) {
            restoreDisplayObjectStanding(wrongTarget);
            wrongTarget.mouseEnabled = false;
          }
          updateFeedbackDisplay(INITIAL_FEEDBACK_TEXT, null);
          endAnswerFeedbackReset(true, () => {
            questionLocked = false;
            // FIX 2: reset arm state so the collision system re-arms for the next attempt
            answerCollisionArmed = false;
            optionContactLocks.clear();
            refreshAnswerContactLocks();
          });
        }, ANSWER_FEEDBACK_MS);
      } else {
        endAnswerFeedbackReset(true, () => {
          questionLocked = false;
          // FIX 2 (fallback path): same reset
          answerCollisionArmed = false;
          optionContactLocks.clear();
        });
      }
    }
  }
}

// ====================== WIN SCENE HELPERS ======================
function hideCongratulations() {
  const seen = new Set();
  const clips = [];

  function add(clip) {
    if (!clip || seen.has(clip)) return;
    seen.add(clip);
    clips.push(clip);
  }

  add(stageRoot.congatulation);
  add(stageRoot.congratulation);
  add(stageRoot.congratulations);
  add(getFirstAvailableClip(["congatulation", "congratulation", "congratulations"]));
  if (typeof collectClipsByName === "function") {
    collectClipsByName(/congrat/i).forEach(add);
  }

  clips.forEach(clip => {
    createjs.Tween.removeTweens(clip);
    clip.visible = false;
    clip.alpha = 1;
    if (clip._originSX != null) clip.scaleX = clip._originSX;
    if (clip._originSY != null) clip.scaleY = clip._originSY;
  });
}

function hideWinScene() {
  hideCongratulations();
  ["videoExit","videoSparkle","videoSparkles","mazeCollapse","periodicTableReveal",
   "victoryBanner","narrationText","scoreDisplay","replayBtn","Periodictable2","periodicTable2",
   "congatulation","congratulation","congratulations"].forEach(name => {
    const clip = stageRoot[name];
    if (!clip) return;
    clip.visible = false; clip.alpha = 1;
    createjs.Tween.removeTweens(clip);
    if (clip._originSX != null) clip.scaleX = clip._originSX;
    if (clip._originSY != null) clip.scaleY = clip._originSY;
    if (clip.htmlElement?.pause) {
      clip.htmlElement.pause();
      clip.htmlElement.currentTime = 0;
    }
  });
}

function getCongratulationClip() {
  return stageRoot.congatulation ||
    stageRoot.congratulation ||
    getFirstAvailableClip(["congatulation", "congratulation", "congratulations"]);
}

function findCongratulationTextField(container) {
  if (!container) return null;

  const directNames = [
    "congratulation_txt",
    "congratulations_txt",
    "congratulationTxt",
    "congratulationText",
    "congrats_txt",
    "txt"
  ];

  for (let i = 0; i < directNames.length; i++) {
    if (container[directNames[i]]) return container[directNames[i]];
  }

  const named = [];
  collectNamedDescendants(container, named, new Set());
  const byName = named.find(child => {
    const name = String(child?.name || "").toLowerCase();
    return name === "congratulation_txt" ||
      name === "congratulations_txt" ||
      name.indexOf("congratulation_txt") !== -1 ||
      name.indexOf("congrat") !== -1 && name.indexOf("txt") !== -1;
  });
  if (byName) return byName;

  return findFirstNonVisualTextDescendant(container);
}

function revealCongratulationText(field, message) {
  if (!field) return false;

  let current = field;
  while (current) {
    current.visible = true;
    current.alpha = 1;
    current = current.parent;
  }

  setDisplayText(field, message);
  if (field.text !== undefined) field.text = message;

  const nested = [];
  collectNamedDescendants(field, nested, new Set());
  nested.forEach(child => {
    if (child && child.text !== undefined) child.text = message;
    if (child) {
      child.visible = true;
      child.alpha = 1;
    }
  });

  bringDisplayObjectToFront(field);
  return true;
}

function bindPlayAgainButton(container) {
  const btn = (container && container.playAgainBtn) ||
    getNamedDescendantByExactName(container, "playAgainBtn") ||
    stageRoot.playAgainBtn;
  if (!btn) return;
  btn.visible = true;
  btn.alpha = 1;
  btn.mouseEnabled = true;
  if (btn.removeAllEventListeners) btn.removeAllEventListeners("click");
  btn.addEventListener("click", restartGame);
}

function showPerfectScoreCongratulations() {
  const clip = getCongratulationClip();
  if (!clip) return false;

  if (clip._originSX == null) {
    clip._originSX = clip.scaleX == null ? 1 : clip.scaleX;
    clip._originSY = clip.scaleY == null ? 1 : clip.scaleY;
  }

  const message = "Congratulations! You scored 100! YOu are a genious!";
  const txt = findCongratulationTextField(clip);
  revealCongratulationText(txt, message);
  if (stageRoot.congratulation_txt) revealCongratulationText(stageRoot.congratulation_txt, message);

  createjs.Tween.removeTweens(clip);
  clip.visible = true;
  clip.alpha = 1;
  clip.scaleX = clip._originSX;
  clip.scaleY = clip._originSY;
  if (clip.parent && clip.parent.setChildIndex) {
    clip.parent.setChildIndex(clip, clip.parent.numChildren - 1);
  }

  createjs.Tween.get(clip, { loop: true })
    .to({
      scaleX: clip._originSX * 1.08,
      scaleY: clip._originSY * 1.08,
      alpha: 1
    }, 520, createjs.Ease.sineInOut)
    .to({
      scaleX: clip._originSX * 0.96,
      scaleY: clip._originSY * 0.96,
      alpha: 0.9
    }, 520, createjs.Ease.sineInOut);

  bindPlayAgainButton(clip);
  return true;
}

function getPeriodictable2Clip() {
  return getFirstAvailableClip(["Periodictable2", "periodicTable2"]);
}

function getPeriodictable2RestartButton() {
  const periodicTable2 = getPeriodictable2Clip();
  if (periodicTable2?.restartbtn || periodicTable2?.restartBtn) {
    return periodicTable2.restartbtn || periodicTable2.restartBtn;
  }

  const namedChildren = [];
  collectNamedDescendants(periodicTable2, namedChildren, new Set());

  return namedChildren.find(child => {
    const name = String(child?.name || "").toLowerCase();
    return name === "restartbtn" || name === "restartbutton";
  }) || stageRoot.restartbtn || stageRoot.restartBtn || null;
}

function restoreGameplayUi() {
  const periodicTable2 = getPeriodictable2Clip();

  if (mazeBg) {
    createjs.Tween.removeTweens(mazeBg);
    mazeBg.visible = true;
    mazeBg.alpha = 1;
  }

  moveButtons.forEach(btn => {
    createjs.Tween.removeTweens(btn);
    btn.visible = true;
    btn.alpha = 1;
    btn.mouseEnabled = true;
  });

  if (timerText) {
    createjs.Tween.removeTweens(timerText);
    timerText.visible = true;
    timerText.alpha = 1;
  }

  if (periodicTable2) {
    createjs.Tween.removeTweens(periodicTable2);
    periodicTable2.visible = false;
    periodicTable2.alpha = 1;
  }

  const congratulation = getCongratulationClip();
  if (congratulation) {
    createjs.Tween.removeTweens(congratulation);
    congratulation.visible = false;
    congratulation.alpha = 1;
    if (congratulation._originSX != null) congratulation.scaleX = congratulation._originSX;
    if (congratulation._originSY != null) congratulation.scaleY = congratulation._originSY;
  }

  const restartBtn = getPeriodictable2RestartButton();
  if (restartBtn) {
    createjs.Tween.removeTweens(restartBtn);
    restartBtn.visible = true;
    restartBtn.alpha = 1;
    restartBtn.mouseEnabled = true;
    restartBtn.removeAllEventListeners("click");
    restartBtn.addEventListener("click", restartGame);
  }
  bindRestartButtons();
}

function transitionToPeriodictable2() {
  const periodicTable2 = getPeriodictable2Clip();
  const fadeTargets = [mazeBg, timerText].concat(moveButtons).filter(Boolean);

  if (periodicTable2) {
    createjs.Tween.removeTweens(periodicTable2);
    if (periodicTable2.gotoAndStop) periodicTable2.gotoAndStop(0);
    periodicTable2.visible = true;
    periodicTable2.alpha = 0;
  }

  fadeTargets.forEach(target => {
    createjs.Tween.removeTweens(target);
    createjs.Tween.get(target).to({ alpha: 0 }, 700).call(() => {
      target.visible = false;
    });
  });

  if (periodicTable2) {
    createjs.Tween.get(periodicTable2).to({ alpha: 1 }, 700);
  }

  const restartBtn = getPeriodictable2RestartButton();
  if (restartBtn) {
    restartBtn.visible = true;
    restartBtn.alpha = 1;
    restartBtn.mouseEnabled = true;
    restartBtn.removeAllEventListeners("click");
    restartBtn.addEventListener("click", restartGame);
  }
  bindRestartButtons();
}

function getClipDurationMs(clip) {
  if (!clip) return 0;

  if (clip.htmlElement?.duration && isFinite(clip.htmlElement.duration)) {
    return clip.htmlElement.duration * 1000;
  }

  const totalFrames = Number(clip.totalFrames) || 0;
  const fps = Number(clip.framerate) || Number(stageRoot.framerate) || Number(createjs.Ticker?.framerate) || 24;
  if (totalFrames > 0 && fps > 0) {
    return (totalFrames / fps) * 1000;
  }

  return 0;
}

function collectNamedDescendants(container, results, seen) {
  if (!container || !container.children) return;

  container.children.forEach(child => {
    if (!child || seen.has(child)) return;
    seen.add(child);

    if (child.name) {
      results.push(child);
    }

    if (child.children && child.children.length) {
      collectNamedDescendants(child, results, seen);
    }
  });
}

function getFirstAvailableClip(names) {
  for (let i = 0; i < names.length; i++) {
    const directClip = stageRoot[names[i]];
    if (directClip) return directClip;
  }

  const namedChildren = [];
  collectNamedDescendants(stageRoot, namedChildren, new Set());

  for (let i = 0; i < names.length; i++) {
    const target = String(names[i]).toLowerCase();

    const exactMatch = namedChildren.find(child => String(child.name).toLowerCase() === target);
    if (exactMatch) return exactMatch;

    const partialMatch = namedChildren.find(child => String(child.name).toLowerCase().includes(target));
    if (partialMatch) return partialMatch;
  }

  return null;
}

function playVideo() {
  let player = window.parent.GetPlayer();
  player.SetVar("activityCompleted", true);
}

// ====================== WIN / CLOSING SCENE ======================
function triggerWin() {
  gameState = "WIN";
  stopQuestionAudio();
  clearAnswerBallLabels();
  if (questionPanel) questionPanel.visible = false;
  if (avatar) avatar.visible = false;

  if (score >= 100 && showPerfectScoreCongratulations()) {
    playVideo();
    return;
  }

  const exitClip = getFirstAvailableClip(["videoExit"]);

  let transitionStarted = false;
  const startTransition = function () {
    if (transitionStarted) return;
    transitionStarted = true;
    transitionToPeriodictable2();
  };

  const exitDuration = getClipDurationMs(exitClip);
  const overlapLead = 450;
  if (exitDuration > 0) {
    setTimeout(startTransition, Math.max(0, exitDuration - overlapLead));
  }

  playVideo();
}

// ====================== SETUP ======================
this.stop();
hideCongratulations();
buildWallData.call(this);
setupGrievers();
if (questionPanel) questionPanel.visible = false;
if (failedScreen)  failedScreen.visible  = false;
hideCongratulations();
updateTimeDisplay();
updateScoreDisplay();
hideWinScene();
restoreGameplayUi();
updateLivesDisplay();
hideAllCheckpoints();

// FIX: wire up the Start button — this listener was missing, which meant
// clicking Start did nothing and the game could never begin.
if (stageRoot.startBtn) {
  stageRoot.startBtn.removeAllEventListeners("click");
  stageRoot.startBtn.addEventListener("click", restartGame);
}

bindRestartButtons();

// Start immediately on browser launch (no Start click required).
// Wait one tick so question text has its designed scale before first show.
if (createjs && createjs.Ticker && createjs.Ticker.addEventListener) {
  const bootStart = function () {
    createjs.Ticker.removeEventListener("tick", bootStart);
    startGame();
  };
  createjs.Ticker.addEventListener("tick", bootStart);
} else {
  startGame();
}
